import {ensureExtraMarket,makeLoan,executeClause,releaseToMarket,signFreeAgent,returnLoans} from './market-extra.js';
import {COUNTRIES,ensureInternational,simulateInternationalStep,internationalArchiveNextSeason} from './international.js';
import {ensureEcosystem,MEDIA,PRESS_QUESTIONS,inspectAcademy,youthTrain,promoteProspect,upgradeFacility,answerPress,careerOffers,acceptCareerJob,seasonAwards,registerAwards,createYouthMatch,createYouthLeague,simulateYouthLeagueRound,governanceSeason,rivalsOf} from './ecosystem.js';
import {restoreSave,saveAll,createCheckpoint,getCheckpoint,protectStorage,readableSaveTime} from './save-system.js';
import {STORAGE_KEY,CUP_GROUPS,load,persist,standings,ranking,leagueMatches,getLeagueNextRound,simulateLeagueRound,scorers,changeCoach,movePlayer,leagueSummary,simulatePostseasonRound,simulateCupRound,createCompetition,simulateCustomRound,played,freshState,validateImport,ensureMarket,openMarket,advanceMarketDay,finishMarket,marketValuation,marketCanManage,submitMarketOffer,acceptMarketCounter,rejectMarketCounter,toggleMarketScout,trainClub,recruitAcademyPlayer,startNextSeason} from './engine.js';
let s=ensureExtraMarket(ensureEcosystem(ensureContinent(ensureMarket(load()))));
let ui={report:null,page:'inicio',table:'annual',round:Math.min(18,getLeagueNextRound(s)),club:'Unión Popular Aurena',clubFilter:'LSV',clubSearch:'',playerQuery:'',shirt:0,team:'Unión Popular Aurena',competition:null,marketSearch:'',marketPos:'TODAS',marketSort:'overall',marketClub:'Unión Popular Aurena',country:'Veltrania',liveMatch:null,liveMinute:0,playing:false,media:'Heraldo'};
const menu=[['inicio','◈','Inicio'],['jornadas','⚽','Jornadas'],['resultados','📰','Resultados y actas'],['clasificaciones','▥','Clasificaciones'],['clubes','⬡','Clubes'],['jugadores','♟','Futbolistas'],['uniformes','👕','Uniformes'],['directivas','♜','Directivas y DT'],['mercado','💰','Mercado de pases'],['fasefinal','🥇','Semifinales y Recopa'],['copa','🏆','Copa Nacional'],['torneos','🌐','Crear torneos'],['mundo','◎','Mundo y países'],['noticias','▤','Periódico'],['historia','✧','Palmarés y partida'],['pais','🌎','Ligas por país'],['arc','🏆','Copas de Arcalis'],['vivo','▶','Partido en vivo 2D'],['prensa','🎙️','Rueda de prensa'],['aficion','📣','Aficiones y clásicos'],['cantera','🌱','Cantera sub-20'],['estadios','🏟️','Estadios y finanzas'],['premios','🥇','Premios individuales'],['museo','🏛️','Museo histórico'],['carrera','🧑‍💼','Mi carrera DT']];
const $=id=>document.getElementById(id);
const E=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const n=v=>Number(v||0).toLocaleString('es-CR');
const club=name=>s.teams[name];
const rndLabel=k=>k===8||k===17?`Jornada ${k} · DOBLE`:k===9||k===18?`Jornada ${k} · CLÁSICOS`:`Jornada ${k}`;
function crest(name,size=''){const t=club(name);if(!t)return '';const ch=(name.split(' ').filter(w=>!['de','del','la'].includes(w.toLowerCase())).map(w=>w[0]).slice(0,2).join('')||'FC');return `<span class="crest ${size}" style="background:linear-gradient(135deg,${E(t.primary)} 48%,${E(t.secondary)} 52%)" title="${E(name)}">${E(ch)}</span>`;}
function toast(text){const d=document.createElement('div');d.className='toast';d.textContent=text;$('toasts').appendChild(d);setTimeout(()=>d.remove(),3400)}
let liveTimer=null;function stopLive(){ui.playing=false;if(liveTimer){clearInterval(liveTimer);liveTimer=null;}}
let saveStatus={message:'Cargando partida…',savedAt:0,ok:false};
let saveToken=0;
function showSaveStatus(){
 document.querySelectorAll('[data-save-status]').forEach(element=>{element.textContent=saveStatus.message;element.classList.toggle('save-error',!saveStatus.ok)});
 document.querySelectorAll('[data-save-time]').forEach(element=>{element.textContent=readableSaveTime(saveStatus.savedAt)});
}
function save(){
 let run;
 const current=++saveToken;
 try{run=saveAll(s,STORAGE_KEY)}catch(error){saveStatus={message:'⚠ Sin guardar · exportá JSON',savedAt:0,ok:false};showSaveStatus();toast('⚠ No se pudo guardar. Exportá tu partida.');return}
 saveStatus={message:'💾 Guardando partida…',savedAt:run.savedAt,ok:true};showSaveStatus();
 run.promise.then(result=>{
  if(current!==saveToken)return;
  const ok=result.localOK||result.indexedOK;
  saveStatus={message:ok?'✓ Partida guardada':'⚠ Sin guardar · exportá JSON',savedAt:ok?result.savedAt:0,ok};
  showSaveStatus();
  if(!ok)toast('⚠ El navegador no permite guardar. Descargá una copia JSON.');
 }).catch(()=>{if(current===saveToken){saveStatus={message:'⚠ Sin guardar · exportá JSON',savedAt:0,ok:false};showSaveStatus()}});
}
const isSaveValid=data=>{try{validateImport(data);return true}catch{return false}};

function nav(p){if(p!=='vivo')stopLive();ui.page=p;window.location.hash='#'+p;render();window.scrollTo({top:0,behavior:'smooth'});}
function head(title,sub,actions=''){return `<div class="top"><div><div class="eyebrow">✦ Noveria · Football Universe</div><h1>${title}</h1><p>${sub}</p></div><div class="controls">${actions}</div></div>`;}
const button=(name,action,extra='',cls='btn')=>`<button class="${cls}" data-action="${action}" ${extra}>${name}</button>`;
function stat(label,value,detail=''){return `<div class="card stat"><div class="label">${label}</div><div class="big">${value}</div>${detail?`<div class="muted small">${detail}</div>`:''}</div>`;}
function scoreFixture(m){let done=played(m);return `<div class="fixture" data-action="match" data-id="${E(m.id)}" role="button" tabindex="0" title="Abrir acta de partido"><div class="host">${crest(m.home)}<div><div class="team">${E(m.home)}</div><div class="meta">Local</div></div></div><div><span class="scorebox">${done?`${m.scoreH} – ${m.scoreA}`:'VS'}</span></div><div class="visitor"><div><div class="team">${E(m.away)}</div><div class="meta">Visitante</div></div>${crest(m.away)}</div></div>`;}
function badgeRound(group,round){return `<span class="tag ${group==='I'?'goldtag':''}">${group==='I'?'INTERZONAL':group==='A'||group==='B'?`ZONA ${group}`:group==='S'?'SEGUNDA':E(group||'COPA')} · ${round}</span>`;}
function table(rows,type='annual',limit=0){const view=limit?rows.slice(0,limit):rows;let body=view.map((r,i)=>{const selected=r.name==='Unión Popular Aurena';const cls=(type==='A'||type==='B')?(i<2?'good':i===rows.length-1?'bad':''):(type==='S'?(i<2?'good':''):(type==='annual'?(i<6?'good':''):''));return `<tr class="${cls} ${selected?'highlight':''}"><td>${i+1}</td><td class="clubname"><span class="link" data-action="club" data-name="${E(r.name)}">${selected?'🔴 ':''}${E(r.name)}</span></td><td>${r.pj}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf}</td><td>${r.gc}</td><td>${r.gd>0?'+':''}${r.gd}</td><td class="bold gold">${r.pts}</td></tr>`}).join('');return `<div class="tablewrap"><table><thead><tr><th>#</th><th style="text-align:left">Equipo</th><th>PJ</th><th>G</th><th>E</th><th>P</th><th>GF</th><th>GC</th><th>DG</th><th>PTS</th></tr></thead><tbody>${body}</tbody></table></div>`;}
function miniTable(group,limit=5){const names={A:'Zona A',B:'Zona B',annual:'Escudo de Oro',S:'Liga de Plata'};return `<div class="card"><div class="between"><h3 class="h3">${names[group]}</h3>${button('Ver tabla →','table',`data-id="${group}"`,'btn sm')}</div>${table(standings(s,group),group,limit)}</div>`}
function newsCard(a){return `<div class="article" data-action="news" data-id="${E(a.id)}"><div class="article-cover" aria-hidden="true"></div><span class="eyebrow">${E(a.category)} · ${E(a.date)}</span><h3>${E(a.title)}</h3><p>${E(a.description)}</p>${a.related?'<div class="gold tiny" style="margin-top:12px">ABRIR PERIÓDICO →</div>':''}</div>`}
function unionPanel(){const t=club('Unión Popular Aurena'),row=standings(s,'B').find(x=>x.name===t.name),pos=standings(s,'B').findIndex(x=>x.name===t.name)+1;const fixtures=s.fixtures.filter(m=>[m.home,m.away].includes(t.name)&&m.competition==='LSV');const next=fixtures.find(m=>!played(m));return `<div class="card" style="background:linear-gradient(130deg,#3b1723,#151d2f 74%);border-color:#64333e"><div class="between"><span class="tag" style="background:#7e2539;color:#fff">🔴⚫ TU CLUB</span>${button('Ver club ↗','club',`data-name="${E(t.name)}"`,'btn sm')}</div><div class="club-heading" style="margin:14px 0">${crest(t.name)}<div><h2 style="margin:0">${E(t.name)}</h2><div class="muted small">Los Obreros · Estadio La Forja</div></div></div><div class="grid three">${statBare('Zona B',pos+'º')}${statBare('Puntos',row.pts)}${statBare('Goles',row.gf+' / '+row.gc)}</div><div class="rule"></div><div class="label">Próximo compromiso</div><div style="margin-top:10px">${next?`<b>${E(next.home)}</b> vs <b>${E(next.away)}</b><div class="small muted">Jornada ${next.round} · ${E(club(next.home).stadium)}</div>`:'Temporada regular completada'}</div><div class="notice" style="margin-top:13px">Seguimiento especial de la Unión en las noticias. <strong>Sin ventajas en las simulaciones.</strong></div></div>`}
function statBare(label,value){return `<div class="mini-kpi"><span class="label">${label}</span><strong>${value}</strong></div>`}
function dashboard(){const summ=leagueSummary(s),next=getLeagueNextRound(s),recent=s.news.slice(0,4);let fixture=s.fixtures.filter(m=>m.competition==='LSV'&&m.round===next).slice(0,4);return `<div class="stack">${head('Centro de mando','Bienvenido a tu universo futbolístico. Cada decisión escribe una nueva página.')}
<div class="hero stadium-photo"><div class="hero-copy"><span class="tag goldtag">★ TEMPORADA · ${s.season}</span><h2>LA HISTORIA<br>LA ESCRIBÍS <span class="gold">VOS.</span></h2><p>9 países con 28 clubes cada uno, entrenadores, fichajes, estadios, uniformes y cientos de futbolistas. El mundo está vivo.</p><div class="controls" style="margin-top:21px">${button(next<=18?`⚽ Simular jornada ${next}`:'✓ Liga regular completada','simulate-league',next>18?'disabled':'','btn primary')}${button('▤ Abrir periódico','nav','data-target="noticias"')}${button('💰 Mercado de pases','nav','data-target="mercado"')}</div></div><div class="pitch"></div></div>
${summ.round>0?`<div class="latest-results"><div><span class="eyebrow">EL HERALDO DE NOVERIA</span><h3>Así terminó la Jornada ${summ.round}</h3><p>Todos los resultados y los periódicos de cada encuentro, a un toque.</p></div>${button('📰 Ver resultados completos','show-results',`data-round="${summ.round}"`,'btn primary')}</div>`:''}<div class="grid four">${stat('Jornadas',`${summ.round}/18`,'Apertura 2026')}${stat('Partidos',n(summ.matches),'Primera y Segunda')}${stat('Goles',n(summ.goals),'Marcadores oficiales')}${stat('Clubes',Object.keys(s.teams).length,'9 países')}</div>
<div class="grid two"><div class="stack"><div class="card"><div class="between"><h2 class="h2">Próxima fecha</h2>${button('Ver todos →','nav','data-target="jornadas"','btn sm')}</div><div class="muted small" style="margin-bottom:14px">${next<=18?rndLabel(next):'Liga regular concluida'}</div>${fixture.length?fixture.map(scoreFixture).join(''):'<div class="empty">No hay partidos pendientes de fase regular.</div>'}</div>${miniTable('annual',6)}</div><div class="stack">${unionPanel()}<div class="card"><div class="between"><h2 class="h2">Últimos titulares</h2>${button('Todas →','nav','data-target="noticias"','btn sm')}</div>${recent.map(a=>`<div class="ticker" style="margin:14px 0;cursor:pointer" data-action="news" data-id="${E(a.id)}"><span class="label">${E(a.category)}</span><div class="bold" style="font-size:13px">${E(a.title)}</div></div>`).join('')}</div></div></div></div>`;}
function reportItem(m){const h=club(m.home),a=club(m.away),known=played(m);
 const goals=(m.events||[]).filter(ev=>ev.type==='goal');
 const streak=goals.length?goals.map(ev=>`<span>${ev.min}' ⚽ ${E(ev.p1Name)} · ${ev.side==='home'?E(m.home):E(m.away)}</span>`).join(''):'<span>Archivo de marcador · Sin autores de gol registrados</span>';
 return `<div class="resultcard" style="--homecolor:${E(h.primary)};--awaycolor:${E(a.primary)}"><div class="result-head"><div class="small muted">${E(h.stadium)} · ${E(h.city)}</div><span class="tag">${m.competition==='LPV'?'LIGA DE PLATA':m.competition==='LSV'?'LIGA SUPREMA':m.competition==='CUP'?'COPA DE PROVINCIAS':m.competition==='POST'?'FASE FINAL':'COPA ESPECIAL'} · ${E(m.group)}</span></div><div class="result-main"><div class="result-team">${crest(m.home,'large')}<strong>${E(m.home)}</strong><span class="muted tiny">LOCAL</span></div><div class="result-score"><strong>${known?`${m.scoreH}<span>:</span>${m.scoreA}`:'VS'}</strong><small>${known?'FINALIZADO':'PENDIENTE'}</small></div><div class="result-team">${crest(m.away,'large')}<strong>${E(m.away)}</strong><span class="muted tiny">VISITANTE</span></div></div><div class="result-goals">${streak}</div><div class="result-bottom"><span class="small">${known&&!m.legacy?E(m.headline||'Partido disputado'):'Marcador oficial'}</span>${button('📰 Leer el periódico','match',`data-id="${E(m.id)}"`,'btn sm')}</div></div>`;
}
function reportResults(round,comp='league',ids=null){ui.report={round,comp,ids};nav('resultados');}
function resultsPage(){let matches=[],label='',sub='';const rr=ui.report;
 if(rr?.ids?.length){matches=rr.ids.map(lookupMatch).filter(Boolean);label=rr.comp||'Competición';sub='Todos los resultados del turno y sus crónicas.';}
 else {const round=rr?.round||leagueSummary(s).round||6;matches=s.fixtures.filter(m=>m.round===round&&['LSV','LPV'].includes(m.competition));label=rndLabel(round);sub='Abrí cualquier partido para leer su periódico completo.';}
 const done=matches.filter(played),goals=done.reduce((n,m)=>n+m.scoreH+m.scoreA,0),groups=[['Zona A',m=>m.competition==='LSV'&&m.group==='A'],['Zona B',m=>m.competition==='LSV'&&m.group==='B'],['Clásicos interzonales',m=>m.competition==='LSV'&&m.group==='I'],['Segunda División',m=>m.competition==='LPV'],['Partidos de copa',m=>!['LSV','LPV'].includes(m.competition)]];
 const union=done.find(m=>m.home==='Unión Popular Aurena'||m.away==='Unión Popular Aurena');
 return `<div class="stack">${head('Resultados de la jornada',sub,button('⚽ Calendario','nav','data-target="jornadas"','btn'))}<div class="report-hero stadium-photo"><span class="tag goldtag">EDICIÓN DEPORTIVA · ${s.season}</span><h2>${E(label)}</h2><p>${done.length} partidos finalizados · ${goals} goles · Crónicas listas para leer</p></div><div class="grid three">${stat('Marcadores',done.length,'Partidos disputados')}${stat('Goles',goals,'En esta tanda')}${stat('Periódicos',done.length,'Abrí cada resultado')}</div>${union?`<div class="union-focus"><div>🔴⚫ <b>La Unión en esta jornada</b><p>${E(union.home)} ${union.scoreH}–${union.scoreA} ${E(union.away)} · ${E(club(union.home).stadium)}</p></div>${button('Ver periódico','match',`data-id="${E(union.id)}"`,'btn sm')}</div>`:''}${groups.map(([title,predicate])=>{const group=matches.filter(predicate);if(!group.length)return '';return `<section class="card reportsection"><div class="between"><h2 class="h2">${title}</h2><span class="tag">${group.length} encuentros</span></div><div class="resultgrid">${group.map(reportItem).join('')}</div></section>`}).join('')}<div class="card"><h2 class="h2">Así queda la clasificación</h2><div class="grid two">${miniTable('A',3)}${miniTable('B',3)}${miniTable('S',3)}${miniTable('annual',5)}</div>${button('Ver las cuatro tablas completas','nav','data-target="clasificaciones"','btn primary')}</div></div>`;
}
function matchesPage(){const rd=ui.round;const ms=s.fixtures.filter(f=>f.round===rd&&['LSV','LPV'].includes(f.competition));const lsv=ms.filter(f=>f.competition==='LSV'),lpv=ms.filter(f=>f.competition==='LPV');const groups=rd===9||rd===18?['I']:['A','B'];let finished=ms.every(played),canPlay=rd===getLeagueNextRound(s);return `<div class="stack">${head('Centro de partido','Partidos, resultados y actas periodísticas desde el primer minuto.',(finished?button('📰 Resultados y crónicas','show-results',`data-round="${rd}"`,'btn primary'):button(`▶ Simular jornada ${rd}`,'simulate-league',(!canPlay||finished)?'disabled':'','btn primary')))}
<div class="card"><div class="between" style="flex-wrap:wrap"><div><div class="eyebrow">CALENDARIO OFICIAL</div><h2 class="h2" style="margin:5px 0">${rndLabel(rd)}</h2><div class="muted small">${rd===8||rd===17?'Dos tandas de partidos de Primera (entre semana).':rd===9||rd===18?'Los nueve clásicos interzonales.':'Fase regular.'}</div></div><div style="min-width:160px"><select id="roundSelect" aria-label="Seleccionar jornada">${Array.from({length:18},(_,i)=>`<option value="${i+1}" ${rd===i+1?'selected':''}>${rndLabel(i+1)}</option>`).join('')}</select></div></div></div>
${groups.map(g=>`<div class="card"><div class="between"><h2 class="h2">${g==='I'?'Clásicos Interzonales':'Primera · Zona '+g}</h2><span class="tag">${lsv.filter(f=>f.group===g).length} partidos</span></div>${[0,1].filter(slot=>lsv.some(f=>f.group===g&&f.slot===slot)).map(slot=>`${rd===8||rd===17?`<div class="eyebrow" style="margin:18px 0 4px">${slot===0?'FECHA ORDINARIA':'FECHA ENTRE SEMANA'}</div>`:''}${lsv.filter(f=>f.group===g&&f.slot===slot).map(scoreFixture).join('')}`).join('')}</div>`).join('')}
<div class="card"><div class="between"><h2 class="h2">Segunda · Liga de Plata</h2><span class="tag">5 partidos</span></div>${lpv.map(scoreFixture).join('')}</div><div class="notice">Las jornadas 1–6 fueron importadas con sus marcadores históricos. Se conserva su puntuación, pero no se inventan sus goleadores ni actas individuales anteriores.</div></div>`}
function standingsPage(){const groups=[['annual','Escudo de Oro'],['A','Zona A'],['B','Zona B'],['S','Liga de Plata']];const k=ui.table;const leader=standings(s,k)[0];return `<div class="stack">${head('Clasificaciones oficiales','Todos los resultados se acumulan automáticamente y no se alteran fechas anteriores.')}
<div class="tabs">${groups.map(([id,label])=>`<button class="${k===id?'selected':''}" data-action="table" data-id="${id}">${label}</button>`).join('')}</div><div class="grid three">${stat('Líder',E(leader.name),`${leader.pts} puntos`)}${stat('Partidos',leader.pj,'Del líder')}${stat('Diferencia',`${leader.gd>0?'+':''}${leader.gd}`,'Goles')}</div><div class="card"><h2 class="h2">${groups.find(x=>x[0]===k)[1]}</h2><p class="muted small">${k==='annual'?'Primer lugar: Escudo de Oro. Top 6: Copa de Campeones. 7.º: repechaje. 8.º al 12.º: Copa Horizonte.':k==='S'?'Primero y segundo: ascenso directo.':'Los primeros dos pasan a semifinales. Solo desciende el último de cada zona.'}</p>${table(standings(s,k),k)}</div></div>`;}
function clubGrid(){const teams=Object.values(s.teams).filter(t=>(ui.clubFilter==='ALL'||t.division===ui.clubFilter||ui.clubFilter===t.country)&&(t.name.toLowerCase().includes(ui.clubSearch.toLowerCase())||t.city.toLowerCase().includes(ui.clubSearch.toLowerCase())));return `<div class="clubgrid">${teams.map(t=>`<div class="clubcard" style="--c1:${t.primary};--c2:${t.secondary}" data-action="club" data-name="${E(t.name)}"><div class="club-heading">${crest(t.name)}<div><h3>${E(t.name)}</h3><span class="muted tiny">${E(t.city)} · ${t.year}</span></div></div><div class="line"></div><div class="sub">${E(t.nickname)} · ${E(t.stadium)}</div><div class="between" style="margin-top:11px"><span class="tag">${t.division==='LSV'?'PRIMERA':t.division==='LPV'?'SEGUNDA':E(t.country.toUpperCase())}</span><span class="gold tiny">OVR ${t.rating}</span></div></div>`).join('')}</div>`;}
function clubsPage(){return `<div class="stack">${head('Los clubes de Noveria','La identidad de cada institución: hinchada, estadio, futbolistas, presupuesto y directiva.')}
<div class="card"><div class="grid two"><div class="field"><span>División o país</span><select id="clubFilter"><option value="ALL">Los 252 clubes</option><option value="LSV" ${ui.clubFilter==='LSV'?'selected':''}>Primera División</option><option value="LPV" ${ui.clubFilter==='LPV'?'selected':''}>Segunda División</option>${FOREIGN_COUNTRIES.map(c=>`<option ${ui.clubFilter===c?'selected':''}>${E(c)}</option>`).join('')}</select></div><div class="field"><span>Buscar club o ciudad</span><input id="clubSearch" class="input" placeholder="Ej. Unión, Miravia, Laguna…" value="${E(ui.clubSearch)}"></div></div></div>${clubGrid()}</div>`;}
function playersPage(){const leaders=scorers(s,15);const all=Object.values(s.teams).flatMap(t=>t.players.map(p=>({...p,club:t.name}))).filter(p=>(p.name+' '+p.club+' '+p.pos).toLowerCase().includes(ui.playerQuery.toLowerCase())).slice(0,150);return `<div class="stack">${head('Centro de futbolistas','Plantillas, valoraciones, potencial, rendimiento, lesiones, asistencias y goleadores.')}
<div class="grid two"><div class="card"><h2 class="h2">Tabla de goleadores</h2>${leaders.length?`<div class="tablewrap"><table><thead><tr><th>#</th><th style="text-align:left">Jugador</th><th>Club</th><th>Goles</th><th>Asis.</th></tr></thead><tbody>${leaders.map((p,i)=>`<tr><td>${i+1}</td><td class="clubname" data-action="player" data-player="${p.id}" data-name="${E(p.club)}">${E(p.name)}</td><td>${E(p.club)}</td><td class="gold bold">${p.goals}</td><td>${p.assists}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">Los goles individuales se contabilizan desde la primera jornada simulada dentro de la aplicación. Las seis fechas antiguas no tienen actas individuales.</p>'}</div><div class="card"><h2 class="h2">Búsqueda de futbolistas</h2><div class="field"><span>Nombre, posición o club</span><input class="input" id="playerSearch" value="${E(ui.playerQuery)}" placeholder="Ej. delantero, Unión, Rafael…"></div><p class="muted small">${Object.values(s.teams).reduce((a,t)=>a+t.players.length,0)} futbolistas registrados en el universo. Hasta 150 coincidencias en pantalla.</p><div class="notice">Todos los jugadores tienen su propia valoración (OVR), potencial, edad, nacionalidad y estadísticas acumulables.</div></div></div>
<div class="card"><h2 class="h2">Directorio de jugadores</h2><div class="tablewrap"><table><thead><tr><th style="text-align:left">Nombre</th><th style="text-align:left">Club</th><th>POS</th><th>Edad</th><th>OVR</th><th>POT</th><th>Goles</th><th>PJ</th></tr></thead><tbody>${all.map(p=>`<tr><td class="clubname" data-action="player" data-player="${p.id}" data-name="${E(p.club)}">${E(p.name)}</td><td style="text-align:left">${E(p.club)}</td><td>${p.pos}</td><td>${p.age}</td><td class="gold bold">${p.ovr}</td><td>${p.pot}</td><td>${p.goals}</td><td>${p.apps}</td></tr>`).join('')}</tbody></table></div></div></div>`;}
function kitSVG(t,ix=0){const kit=t.kits[ix]||t.kits[0];const id='pat'+ix+'-'+Math.abs((t.name.length*13+t.name.charCodeAt(0))%1000);const pattern=kit.pattern==='stripes'?`<rect x="56" y="32" width="29" height="191" fill="${kit.s}" opacity=".9"/><rect x="109" y="32" width="24" height="191" fill="${kit.s}" opacity=".9"/><rect x="155" y="32" width="23" height="191" fill="${kit.s}" opacity=".9"/>`:kit.pattern==='hoops'?`<rect x="56" y="85" width="128" height="25" fill="${kit.s}"/><rect x="56" y="145" width="128" height="25" fill="${kit.s}"/>`:kit.pattern==='diagonal'?`<path d="M34 192 L170 30 L194 60 L57 219 Z" fill="${kit.s}"/>`:kit.pattern==='half'?`<path d="M120 31H184V223H120Z" fill="${kit.s}"/>`:'';return `<svg viewBox="0 0 240 250" role="img" aria-label="Uniforme ${E(t.name)}"><defs><clipPath id="${id}"><path d="M79 25 L100 14 L140 14 L161 25 L204 54 L225 108 L184 130 L180 224 L60 224 L56 130 L15 108 L36 54 Z"/></clipPath></defs><path d="M79 25 L100 14 L140 14 L161 25 L204 54 L225 108 L184 130 L180 224 L60 224 L56 130 L15 108 L36 54 Z" fill="${E(kit.p)}" stroke="#e6e7f5" stroke-opacity=".45" stroke-width="2"/><g clip-path="url(#${id})">${pattern}<path d="M89 18 L105 41 L135 41 L151 18" fill="#0d1929" stroke="${E(kit.s)}" stroke-width="6"/><path d="M56 126 L16 103 M184 126 L223 103" stroke="${E(kit.s)}" stroke-width="12"/></g><text x="120" y="115" text-anchor="middle" font-family="Arial,sans-serif" font-size="10" font-weight="800" fill="#ffffff" paint-order="stroke" stroke="#18202b" stroke-width="2">${E(kit.sponsor.slice(0,18).toUpperCase())}</text><text x="120" y="182" text-anchor="middle" font-family="Arial,sans-serif" font-size="49" font-weight="900" fill="#ffffff" paint-order="stroke" stroke="#17202c" stroke-width="3">11</text></svg>`;}
function kitsPage(){let t=club(ui.team),ix=ui.shirt;return `<div class="stack">${head('Diseñador de uniformes','Editá colores, patrones y patrocinadores de los tres kits de cualquier club.')}
<div class="card"><div class="field"><span>Elegir institución</span><select id="kitClub">${Object.values(s.teams).map(c=>`<option ${c.name===t.name?'selected':''}>${E(c.name)}</option>`).join('')}</select></div></div><div class="kits">${['LOCAL','VISITANTE','TERCER KIT'].map((name,i)=>`<div class="kitbox ${ix===i?'current':''}" data-action="shirt" data-id="${i}">${kitSVG(t,i)}<div class="tag">${name} ${ix===i?'✓':''}</div></div>`).join('')}</div>
<div class="grid two"><div class="kit-large">${kitSVG(t,ix)}<div class="muted small">Vista previa del uniforme seleccionado</div></div><div class="card"><h2 class="h2">Personalización</h2><form id="kitForm" class="form"><div class="grid two"><label class="field"><span>Color principal</span><input type="color" name="p" value="${E(t.kits[ix].p)}"></label><label class="field"><span>Color secundario</span><input type="color" name="s" value="${E(t.kits[ix].s)}"></label></div><label class="field"><span>Patrón</span><select name="pattern">${[['stripes','Rayas verticales'],['hoops','Franjas horizontales'],['diagonal','Banda diagonal'],['half','Mitades'],['plain','Liso']].map(([v,l])=>`<option value="${v}" ${t.kits[ix].pattern===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Patrocinador ficticio</span><input class="input" name="sponsor" value="${E(t.kits[ix].sponsor)}" maxlength="18"></label><button class="btn primary" type="submit">Guardar uniforme</button></form><p class="muted small">Los diseños se guardan con tu partida y se pueden modificar las veces que quieras.</p></div></div></div>`;}
function officePage(){const t=club(ui.team);return `<div class="stack">${head('Directivas y entrenadores','Contratos, presidentes, técnicos, tácticas, despidos y mercado de transferencias.')}
<div class="card"><div class="grid two"><label class="field"><span>Club a gestionar</span><select id="manageClub">${Object.values(s.teams).map(x=>`<option ${x.name===t.name?'selected':''}>${E(x.name)}</option>`).join('')}</select></label><label class="field"><span>Modo de juego</span><select id="modeSelect"><option value="president" ${s.mode==='president'?'selected':''}>Presidente de la Federación</option><option value="manager" ${s.mode==='manager'?'selected':''}>Modo entrenador</option></select></label></div></div>
<div class="grid two"><div class="card"><div class="club-heading">${crest(t.name)}<div><h2 class="h2">${E(t.name)}</h2><div class="muted small">${E(t.stadium)}</div></div></div><div class="rule"></div>${[['Presidente',t.president],['Director deportivo',t.director],['Director técnico',t.coach],['Presupuesto',t.budget.toFixed(1)+' M VLR'],['Confianza directiva',t.board+' / 100'],['Moral del plantel',t.morale+' / 100']].map(([l,v])=>`<div class="between" style="padding:7px 0"><span class="muted small">${l}</span><strong class="small">${E(v)}</strong></div>`).join('')}<div class="rule"></div>${button('Destituir / fichar entrenador','coach',`data-name="${E(t.name)}"`,'btn danger')}</div>
<div class="card"><h2 class="h2">Oficina del DT</h2><form id="tacticsForm" class="form"><label class="field"><span>Alineación base</span><select name="formation">${['4-3-3','4-4-2','4-2-3-1','3-5-2','5-3-2'].map(x=>`<option ${t.formation===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Estilo táctico</span><select name="tactic">${['Equilibrado','Posesión','Presión alta','Contraataque'].map(x=>`<option ${t.tactic===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn primary" type="submit">Guardar táctica del equipo</button></form><div class="rule"></div><div class="label">Cambios de entrenador</div>${t.coachHistory.length?t.coachHistory.map(h=>`<div class="muted small" style="margin:7px 0">J${h.round}: ${E(h.out)} → ${E(h.in)}</div>`).join(''):'<p class="muted small">No se han producido destituciones desde que empezó la simulación.</p>'}</div></div>
<div class="card"><h2 class="h2">💰 Despacho del mercado</h2><p class="muted small">Modo carrera con negociaciones, contraofertas, contratos y traspasos automáticos de todos los países.</p><div class="notice">${s.mode==='manager'?`Sos DT de ${E(s.managedClub)}. Solo podés fichar para tu equipo.`:'Como presidente de la federación podés gestionar cualquier club.'}</div><div style="margin-top:16px">${button('Ir al mercado de pases →','nav','data-target="mercado"','btn primary')}</div></div></div>`;}
function marketBuyer(){return s.mode==='manager'?s.managedClub:ui.marketClub;}
function marketBadge(status){return {accepted:'✔ FICHAJE',counter:'↪ CONTRAOFERTA',rejected:'✕ RECHAZADA',declined:'✕ DESCARTADA',expired:'⌛ CADUCADA'}[status]||status;}
function marketPageBase(){ensureMarket(s);const m=s.market,buyer=marketBuyer(),buy=club(buyer),open=m.status==='open';
 const all=Object.values(s.teams).flatMap(t=>t.name===buyer?[]:t.players.map(p=>({...p,team:t.name,price:marketValuation(p)})));
 let rows=all.filter(p=>ui.marketPos==='TODAS'||p.pos===ui.marketPos).filter(p=>(p.name+' '+p.team+' '+p.nationality).toLowerCase().includes(ui.marketSearch.toLowerCase()));
 rows.sort(ui.marketSort==='cheap'?(a,b)=>a.price-b.price:ui.marketSort==='potential'?(a,b)=>b.pot-a.pot:(a,b)=>b.ovr-a.ovr);
 const watch=new Set(m.shortlist),watchPlayers=all.filter(p=>watch.has(p.id)),offers=m.offers.filter(x=>x.buyer===buyer),log=m.log.slice(0,36);
 return `<div class="stack">${head('Mercado de pases','Negociaciones, ojeadores, contratos, presupuestos y una ventana de fichajes automática.',button('♟ Oficina del DT','nav','data-target="directivas"'))}
 <div class="market-cover stadium-photo"><div><span class="tag goldtag">NOVERIA MERCADO · EDICIÓN ${s.season}</span><h2>EL PRÓXIMO<br><span class="gold">GRAN FICHAJE</span></h2><p>Fichá como en un modo carrera: ofertá, negociá salarios y respondé contraofertas. Los demás clubes también toman decisiones.</p></div></div>
 <div class="grid four">${stat('Ventana',open?'ABIERTA':'CERRADA',open?`Día ${m.day} de ${m.maxDays}`:'Podés abrir otra ventana')}${stat('Mi presupuesto',n(buy.budget.toFixed(2))+' M','Velar · VLR')}${stat('Operaciones',m.log.length,'En esta ventana')}${stat('Plantilla',buy.players.length+' / 30','Mínimo 17 futbolistas')}</div>
 <div class="card market-hub"><div class="between"><div><div class="eyebrow">DESPACHO DEL DIRECTOR DEPORTIVO</div><h2 class="h2">${E(m.title)}</h2><p class="small muted">${open?'Cada día los clubes negocian de forma autónoma. En el día 12 se dispara la actividad del cierre.':'Podés abrir una ventana ahora o esperar a que se abra al terminar la fase regular.'}</p></div><span class="tag ${open?'goldtag':''}">${open?'● MERCADO ABIERTO':'○ CERRADO'}</span></div>
 ${open?`<div class="deadline-track"><div style="width:${Math.round(m.day/m.maxDays*100)}%"></div></div><div class="controls">${button('⏭ Avanzar un día','market-next','','btn primary')}${button('⚡ Simular hasta el cierre','market-finish','','btn')}${button('🏋 Entrenar promesas','market-train','','btn')}${button('🌱 Fichar canterano','market-academy','','btn')}</div>`:`<div class="controls">${button('🚀 Abrir ventana de pases','market-open','','btn primary')}</div>`}
 ${m.lastReport?`<div class="notice" style="margin-top:13px">Último cierre: ${m.lastReport.transfers} fichajes (${m.lastReport.automatic} automáticos) · ${m.lastReport.totalSpent.toFixed(2)} M VLR negociados.</div>`:''}</div>
 <div class="grid two"><div class="card"><div class="eyebrow">MODO CARRERA</div><h2 class="h2">Tu despacho de fichajes</h2>${s.mode==='manager'?`<div class="notice">Dirigís exclusivamente a <b>${E(s.managedClub)}</b>. Los otros clubes tienen sus propias directivas.</div>`:`<label class="field"><span>Club al que querés llevar refuerzos</span><select id="marketClubSelect">${Object.values(s.teams).map(t=>`<option value="${E(t.name)}" ${buyer===t.name?'selected':''}>${E(t.name)}</option>`).join('')}</select></label>`}<div class="grid two" style="margin-top:12px">${statBare('Club',E(buyer))}${statBare('Presupuesto',buy.budget.toFixed(2)+' M VLR')}</div><div class="rule"></div><p class="muted small">Los precios incluyen la negociación entre directivas. Los salarios se expresan en miles de VLR mensuales y los contratos duran de 1 a 5 años.</p></div>
 <div class="card"><div class="eyebrow">MI AGENDA DE NEGOCIACIONES</div><h2 class="h2">Ofertas y contraofertas</h2>${offers.length?offers.slice(0,9).map(o=>`<div class="market-event"><div><strong>${E(o.player)}</strong><div class="muted tiny">${E(o.seller)} → ${E(o.buyer)} · ${o.fee.toFixed(2)} M</div><span class="tag">${marketBadge(o.status)}</span></div>${o.status==='counter'?`<div class="controls">${button('Aceptar '+o.asking.toFixed(2)+' M','market-accept',`data-id="${E(o.id)}"`,'btn sm primary')}${button('Rechazar','market-decline',`data-id="${E(o.id)}"`,'btn sm')}</div>`:o.reason?`<span class="tiny muted">${E(o.reason)}</span>`:''}</div>`).join(''):'<div class="empty">No hay ofertas. <strong>¡Buscá tu primer fichaje!</strong></div>'}</div></div>
 <div class="card"><div class="between"><div><div class="eyebrow">SCOUTING NETWORK · 9 PAÍSES</div><h2 class="h2">Buscador mundial de futbolistas</h2></div><span class="tag">${rows.length} futbolistas</span></div><form id="marketSearchForm" class="market-filters"><label class="field"><span>Nombre, club o nacionalidad</span><input name="search" class="input" value="${E(ui.marketSearch)}" placeholder="Ej. delantero, Aurena, Varkosia…" /></label><label class="field"><span>Posición</span><select name="pos">${['TODAS','POR','DFC','LD','LI','MCD','MC','MCO','MD','MI','MP','EI','ED','DC'].map(pos=>`<option ${pos===ui.marketPos?'selected':''}>${pos}</option>`).join('')}</select></label><label class="field"><span>Ordenar</span><select name="sort">${[['overall','Mejor valoración'],['cheap','Menor precio'],['potential','Mayor potencial']].map(([v,label])=>`<option value="${v}" ${v===ui.marketSort?'selected':''}>${label}</option>`).join('')}</select></label><button class="btn primary" type="submit">🔎 Buscar</button></form>
 <div class="tablewrap"><table><thead><tr><th>POS</th><th style="text-align:left">Jugador</th><th style="text-align:left">Club</th><th>OVR</th><th>POT</th><th>Edad</th><th>Valor</th><th>Acciones</th></tr></thead><tbody>${rows.slice(0,55).map(p=>`<tr><td>${p.pos}</td><td class="clubname" data-action="player" data-player="${p.id}" data-name="${E(p.team)}">${E(p.name)}</td><td style="text-align:left">${E(p.team)}</td><td class="gold bold">${p.ovr}</td><td>${p.pot}</td><td>${p.age}</td><td>${p.price.toFixed(2)} M</td><td><div class="controls">${button('⚑','market-scout',`data-id="${E(p.id)}"`,'btn sm')}${button(open?'Ofertar':'Cerrado','market-offer',`data-name="${E(p.team)}" data-id="${E(p.id)}" ${open?'':'disabled'}`,'btn sm primary')}</div></td></tr>`).join('')}</tbody></table></div><div class="muted tiny" style="margin-top:10px">Hasta 55 resultados visibles. Refiná los filtros para encontrar a tu próximo fichaje.</div></div>
 <div class="grid two"><div class="card"><h2 class="h2">⚑ Lista de seguimiento</h2>${watchPlayers.length?watchPlayers.slice(0,20).map(p=>`<div class="market-event"><span>${E(p.name)} · ${E(p.pos)} · OVR ${p.ovr}<div class="muted tiny">${E(p.team)} · ${p.price.toFixed(2)} M</div></span>${button('Ofertar','market-offer',`data-name="${E(p.team)}" data-id="${E(p.id)}" ${open?'':'disabled'}`,'btn sm')}</div>`).join(''):'<p class="muted small">Marcá a tus prospectos con ⚑ desde el buscador.</p>'}</div>
 <div class="card"><h2 class="h2">🗞 Transferencias confirmadas</h2>${log.length?log.map(t=>`<div class="market-event"><div><strong>${E(t.player)}</strong><div class="muted tiny">${E(t.from)} → ${E(t.to)}</div></div><span class="gold bold small">${t.fee.toFixed(2)} M</span></div>`).join(''):'<p class="muted small">Todavía no se han cerrado operaciones en esta ventana.</p>'}</div></div></div>`;
}
function marketPage(){return marketPageBase()+extraMarketPage();}
function extraMarketPage(){ensureExtraMarket(s);const buyer=marketBuyer();const t=club(buyer),opened=s.market.status==='open',list=Object.values(s.teams).filter(x=>x.name!==buyer&&x.players.length>17).flatMap(team=>team.players.slice(11,13).map(p=>({team,p}))).slice(0,36);
return `<div class="stack" style="margin-top:18px"><div class="card"><div class="eyebrow">NOVERIA 4 · MODO CARRERA</div><h2 class="h2">🤝 Mercado extremo · Cesiones y cláusulas</h2><p class="muted small">Buscá jugadores y ejecutá préstamos de una temporada, cláusulas de rescisión y contratos de agentes libres. Solo podés negociar con una ventana abierta. Cada movimiento queda en el historial.</p><div class="grid three">${stat('Mercado',opened?'ABIERTO':'CERRADO','Negociaciones')}${stat('Agentes libres',s.freeAgents.length,'Sin contrato')}${stat('Cesiones activas',s.loans.length,'Regresan al terminar el año')}</div></div>
<div class="card"><h2 class="h2">✍️ Futbolistas libres</h2><div class="grid two">${s.freeAgents.slice(0,16).map(p=>`<div class="market-event"><div><strong>${E(p.name)}</strong><div class="muted small">${E(p.pos)} · ${p.age} años · OVR ${p.ovr} · ${E(p.nationality)}</div></div>${button('Firmar libre','market-free',`data-id="${E(p.id)}" ${!opened?'disabled':''}`,'btn sm')}</div>`).join('')}</div></div>
<div class="card"><h2 class="h2">🔥 Cláusulas y préstamos de clubes</h2><div class="grid two">${list.map(({team,p})=>`<div class="market-event"><div><strong>${E(p.name)}</strong><div class="muted small">${E(team.name)} · ${E(p.pos)} · ${p.ovr} OVR</div><div class="tiny gold">Cláusula: ${(marketValuation(p)*1.7).toFixed(2)} M VLR</div></div><div class="controls">${button('Cesión','market-loan',`data-id="${E(p.id)}" data-seller="${E(team.name)}" ${!opened?'disabled':''}`,'btn sm')}${button('Rescindir cláusula','market-clause',`data-id="${E(p.id)}" data-seller="${E(team.name)}" ${!opened?'disabled':''}`,'btn sm gold')}</div></div>`).join('')}</div></div>
<div class="card"><h2 class="h2">📋 Rescindir contrato de mi plantilla</h2><div class="grid two">${t.players.slice(14,19).map(p=>`<div class="market-event"><span><strong>${E(p.name)}</strong><div class="muted small">OVR ${p.ovr} · ${E(p.pos)}</div></span>${button('Dar carta de libertad','market-release',`data-id="${E(p.id)}" ${!opened?'disabled':''}`,'btn danger sm')}</div>`).join('')}</div></div></div>`;}
function marketOfferModal(seller,id){ensureMarket(s);const p=club(seller)?.players.find(p=>String(p.id)===String(id)),buyer=marketBuyer(),t=club(buyer);if(!p||!t){toast('El jugador ya no está disponible');return;}
 if(s.market.status!=='open'){toast('Debés abrir el mercado');return;}
 const value=marketValuation(p);modal('Mesa de negociaciones · '+p.name,`<div class="stack"><div class="market-negotiation"><div><div class="eyebrow">NOVERIA CAREER MODE</div><h2>${E(p.name)}</h2><p>${E(seller)} · ${E(p.pos)} · ${p.age} años</p></div><div class="market-ovr">${p.ovr}</div></div><div class="grid three">${statBare('Valor estimado',value.toFixed(2)+' M VLR')}${statBare('Salario actual',n(p.salary)+' mil/mes')}${statBare('Caja disponible',t.budget.toFixed(2)+' M')}</div>
 <form id="marketOfferForm" class="form"><input type="hidden" name="seller" value="${E(seller)}"><input type="hidden" name="playerId" value="${E(p.id)}"><input type="hidden" name="buyer" value="${E(buyer)}"><label class="field"><span>Oferta al club vendedor (millones VLR)</span><input class="input" type="number" name="fee" min="0.05" max="999" step="0.01" value="${(value*1.14).toFixed(2)}" required></label><div class="grid two"><label class="field"><span>Salario propuesto (miles VLR/mes)</span><input class="input" type="number" name="wage" min="15" max="10000" step="1" value="${Math.round(p.salary*1.2)}" required></label><label class="field"><span>Años de contrato</span><select name="years">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===3?'selected':''}>${n} años</option>`).join('')}</select></label></div><div class="notice">El vendedor puede aceptar, rechazar o pedir más dinero. No hay fichajes garantizados; también deben cumplirse las reglas de plantillas y presupuesto.</div><button class="btn primary" type="submit">✉ Enviar oferta formal</button></form></div>`);
}
function cupPage(){const c=s.cup,rd=c.round,ms=c.fixtures.filter(f=>f.round===rd),groups=CUP_GROUPS.map((clubs,i)=>({id:String.fromCharCode(65+i),r:ranking(c.fixtures,clubs)}));return `<div class="stack">${head('Copa de las Provincias','28 clubes, siete grupos y eliminatorias a partido único. El sueño de los humildes.',button(c.champion?'🏆 Campeón proclamado':`▶ Jugar ${c.phase==='groups'?'fecha '+rd:c.phase}`,'simulate-cup',c.champion?'disabled':'','btn primary'))}
<div class="hero stadium-photo" style="min-height:220px"><div class="hero-copy"><span class="tag goldtag">COPA NACIONAL · 2026</span><h2 style="font-size:38px">UNA COPA.<br><span class="gold">28 SUEÑOS.</span></h2><p>Primera y Segunda juntas. Todos comienzan sin títulos.</p></div><div class="pitch"></div></div><div class="card"><div class="between"><h2 class="h2">${c.champion?'🏆 Campeón: '+E(c.champion):c.phase==='groups'?`Grupos · Fecha ${rd}/3`:'Eliminatorias · '+c.phase.toUpperCase()}</h2><span class="tag">${ms.length} partidos</span></div>${ms.length?ms.map(scoreFixture).join(''):'Sin partidos programados'}</div>
${c.phase==='groups'?`<div class="grid two">${groups.map(g=>`<div class="card"><h3 class="h3">GRUPO ${g.id}</h3>${table(g.r,'custom')}</div>`).join('')}</div>`:`<div class="card"><h2 class="h2">Camino a la final</h2>${c.fixtures.filter(f=>!(/^[A-G]$/.test(f.group))).map(m=>`<div class="muted small" style="margin:7px 0">${E(m.group)} · ${E(m.home)} ${played(m)?m.scoreH+'-'+m.scoreA:'vs'} ${E(m.away)} ${m.winner?'→ '+E(m.winner):''}</div>`).join('')}</div>`}</div>`;}
function postseasonPage(){const p=s.postseason||{stage:'locked',fixtures:[]};const title=p.stage==='locked'?'Se abre después de la Jornada 18':p.stage==='finalizada'?'La primera temporada tiene sus campeones':`En juego · ${p.stage}`;let fixtures=p.fixtures||[];return `<div class="stack">${head('Fase final y Recopa',title,button(p.stage==='locked'?'🔒 Aún no disponible':p.stage==='finalizada'?'✓ Campeonato terminado':'▶ Jugar '+p.stage+' · '+(p.leg===1?'ida':'vuelta'),'simulate-post',(p.stage==='locked'||p.stage==='finalizada')?'disabled':'','btn primary'))}<div class="grid three">${stat('Campeón Apertura',p.apertura?E(p.apertura):'Por definir','Premio: 10.000 VLR')}${stat('Escudo de Oro',s.honours.find(h=>h.title==='Escudo de Oro de Veltrania')?.winner||'Por definir','Mejor de la tabla anual')}${stat('Recopa Veltrana',p.recopa?E(p.recopa):'Por definir','Final a partido único')}</div><div class="card"><h2 class="h2">Reglamento de la fase final</h2><p class="muted small">Los dos primeros de cada zona juegan semifinales 1.º vs 4.º y 2.º vs 3.º según la tabla anual. Semifinales y final a ida y vuelta; siempre cierra de local el mejor clasificado. Si hay empate en el global, prórroga y penales. Recopa a partido único entre campeón del Apertura y campeón anual. Si ambos son el mismo club, participa el subcampeón anual.</p>${p.stage==='locked'?'<div class="notice">Todavía estamos en fase regular. La fase final se habilita automáticamente después de la Jornada 18.</div>':''}</div><div class="card"><h2 class="h2">Resultados de las eliminatorias</h2>${fixtures.length?fixtures.map(m=>`<div><div class="eyebrow" style="margin:12px 0 2px">${E(m.group).toUpperCase()} · ${m.extraTime?'PRÓRROGA · ':''} ${m.round===1?'IDA / PARTIDO ÚNICO':'VUELTA'}</div>${scoreFixture(m)}${m.penalties?`<span class="tag goldtag">Penales: ${E(m.penalties)}</span>`:''}</div>`).join(''):'<div class="empty">🏆<strong>Esperando a los cuatro semifinalistas.</strong></div>'}</div></div>`;}
const FORMAT_LABELS={league:'Liga · una vuelta',league2:'Liga · ida y vuelta',cup:'Eliminación directa',recopa:'Recopa · final neutral',groups:'Grupos y eliminatorias',apertura:'Apertura con zonas + finales + Recopa'};
function compPage(){const selected=ui.competition&&s.competitions.find(c=>c.id===ui.competition);const selectable=Object.values(s.teams).filter(t=>t.division!=='EXT');const foreign=[];return `<div class="stack">${head('Fábrica de torneos','Creá Recopas, Supercopas, ligas ida/vuelta y copas continentales con grupos. Cada trofeo entra al palmarés.')}
<div class="stadium-band stadium-photo"><div><span class="tag goldtag">LA GLORIA TAMBIÉN SE INVENTA</span><h2>CADA COPA TIENE UNA HISTORIA.</h2><p>Desde una final única en cancha neutral hasta un campeonato entre países.</p></div></div>
<div class="grid two"><div class="card"><h2 class="h2">🏆 Crear un torneo</h2><form id="createCompForm" class="form"><label class="field"><span>Nombre de la competición</span><input name="name" class="input" required maxlength="65" placeholder="Ej. Recopa Continental de Arcalis"></label><label class="field"><span>Elegí el formato</span><select name="format" id="formatSelect">${Object.entries(FORMAT_LABELS).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><div class="formathelp" id="formatHelp">Todos contra todos, una vuelta. Los puntos deciden al campeón.</div><label class="field"><span>Premio al campeón (VLR)</span><input class="input" name="prize" type="number" min="0" max="10000000" value="10000"></label><label class="field"><span>Participantes (Ctrl/Cmd para seleccionar varios)</span><select name="teams" id="customTeams" multiple required>${selectable.map(t=>`<option value="${E(t.name)}">${E(t.name)} · ${E(t.division==='LSV'?'Primera':'Segunda')} · ${E(t.country)}</option>`).join('')}<optgroup label="CLUBES DEL EXTRANJERO">${foreign.map(t=>`<option value="${E(t.name)}">${E(t.name)} · ${E(t.country)}</option>`).join('')}</optgroup></select></label><p class="small muted">Recopa: exactamente 2 clubes · Grupos: múltiplos de 4 · Resto: de 2 a 32 participantes.</p><button class="btn primary" type="submit">+ FUNDAR COMPETICIÓN</button></form></div>
<div class="card"><h2 class="h2">Sala de trofeos</h2><div class="trophywall">${['🏆','🥇','🌟','⚽'].map((t,i)=>`<div class="trophy-mini"><span>${t}</span>${['COPAS','RECOPAS','TORNEOS','LIGAS'][i]}</div>`).join('')}</div><h3 class="h3">Tus torneos</h3>${s.competitions.length?s.competitions.map(c=>`<div class="between" style="gap:9px;padding:12px 0;border-bottom:1px solid var(--line)"><div><strong>🏆 ${E(c.name)}</strong><div class="muted small">${FORMAT_LABELS[c.type]||'Copa'} · ${c.teams.length} clubes · ${c.champion?'Campeón: '+E(c.champion):'Ronda '+c.round}</div></div>${button('Entrar ↗','custom-open',`data-id="${E(c.id)}"`,'btn sm')}</div>`).join(''):'<div class="empty">Todavía no hay torneos propios.<strong>¡Fundá el primero!</strong></div>'}<div class="notice">Las Copas oficiales de Arcalis se juegan desde la sección internacional, además de los torneos personalizados.</div></div></div>
${selected?`<div class="card"><div class="between" style="flex-wrap:wrap"><div><div class="eyebrow">CENTRO DE COMPETICIÓN</div><h2 class="h2">🏆 ${E(selected.name)}</h2><p class="small muted">${FORMAT_LABELS[selected.type]||'Copa'} · ${E(selected.stage)} · ${selected.teams.length} participantes</p></div><div class="controls">${button(selected.champion?'🏆 Campeón: '+E(selected.champion):'▶ SIMULAR RONDA '+selected.round,'simulate-custom',`data-id="${E(selected.id)}" ${selected.champion?'disabled':''}`,'btn primary')}${button('Ver resultados','comp-report',`data-id="${E(selected.id)}"`,'btn')}</div></div>${['league','league2'].includes(selected.type)?table(ranking(selected.fixtures,selected.teams),'custom'):''}${selected.type==='groups'&&selected.groups?.length?`<div class="grid two">${selected.groups.map(g=>`<div class="card inner"><h3 class="h3">Grupo ${g.id}</h3>${table(ranking(selected.fixtures.filter(f=>f.group===g.id),g.teams),'custom')}</div>`).join('')}</div>`:''}<div class="rule"></div><div class="eyebrow">MARCADOR Y CALENDARIO · FECHA ${selected.round}</div>${selected.fixtures.filter(m=>m.round===selected.round).map(scoreFixture).join('')}${selected.champion?`<div class="notice">🏆 ${E(selected.champion)} se incorpora al palmarés oficial de 2026.</div>`:''}</div>`:''}</div>`;}
function worldPage(){const countries=COUNTRIES;return `<div class="stack">${head('Arcalis · Nueve países','252 clubes, 9 primeras divisiones, 9 segundas y dos grandes copas continentales.')}
<div class="hero stadium-photo"><div class="hero-copy"><span class="tag goldtag">NOVERIA 4.0 · MODO CONTINENTE</span><h2>NUEVE NACIONES.<br><span class="gold">UNA PASIÓN.</span></h2><p>Elegí un país para revisar sus resultados, posiciones, clásicos, ascensos, descensos y títulos. Todos compiten con el reglamento veltrano.</p></div><div class="pitch"></div></div>
<div class="grid three">${countries.map(c=>{const rows=countryRows(c,'annual'),w=s.world?.[c];return `<button class="country country-button" data-action="select-country" data-country="${E(c)}"><span class="eyebrow">PAÍS DE ARCALIS · ${c==='Veltrania'?'SEDE PRINCIPAL':'FEDERACIÓN AFILIADA'}</span><h3 class="h3">🌐 ${E(c)}</h3><p class="muted small">28 clubes · Primera 18 · Segunda 10</p><div class="small gold">${c==='Veltrania'?'Capital Aurena':E(PROFILES[c]?.capital||'')} · J${c==='Veltrania'?getLeagueNextRound(s)-1:w?.round||0}/18</div><div class="muted small" style="margin-top:12px">${rows[0]?`🏅 Líder: ${E(rows[0].name)} · ${rows[0].pts} pts`:''}</div><span class="tiny gold">ENTRAR A LA LIGA →</span></button>`}).join('')}</div>
<div class="card"><div class="between"><h2 class="h2">🏆 Copa de Campeones y Copa Horizonte</h2>${button('Abrir competiciones','nav','data-target="arc"','btn primary')}</div><p class="small muted">6 plazas directas por país a Campeones; el 7.º juega repechaje contra el 13.º de otro país. Los puestos 8.º al 12.º entran a Horizonte. Grupos internacionales y cruces eliminatorios.</p></div></div>`;}
function countryRows(c,g){return c==='Veltrania'?standings(s,g):countryStandings(s,c,g);}
function countryPage(){const c=ui.country||'Veltrania',w=s.world?.[c],r=c==='Veltrania'?getLeagueNextRound(s)-1:w?.round||0,fixtureList=c==='Veltrania'?s.fixtures:(w?.fixtures||[]),upcoming=Math.min(18,r+1),past=fixtureList.filter(m=>m.round===r&&played(m));const future=fixtureList.filter(m=>m.round===upcoming&&!played(m));const p=c==='Veltrania'?s.postseason:w?.postseason;const profile=PROFILES[c];return `<div class="stack">${head('Federación de '+c,(profile?.trait||'La cuna de nuestro fútbol')+' · Apertura '+s.season,button('◈ Ver los nueve países','nav','data-target="mundo"','btn'))}
<div class="card country-banner"><div class="eyebrow">${c==='Veltrania'?'CAPITAL AURENA':E(profile?.capital||'')} · ${E(profile?.land||'ARALIS')}</div><h2>⚽ ${E(c.toUpperCase())} <span class="gold">${s.season}</span></h2><p>18 clubes en Primera · 10 en Segunda · Zonas A/B · 2 descensos · 2 ascensos · finales ida/vuelta + Recopa</p><div class="controls">${c==='Veltrania'?button(r<18?'▶ JUGAR JORNADA '+upcoming:'Liga finalizada','simulate-league',r>=18?'disabled':'','btn primary'):button(r<18?'▶ SIMULAR JORNADA '+upcoming:'Liga finalizada','sim-country',`data-country="${E(c)}" ${r>=18?'disabled':''}`,'btn primary')}${c!=='Veltrania'?button(w?.cup?.champion?'🏆 Copa: '+E(w.cup.champion):'🏆 Simular Copa Nacional','sim-country-cup',`data-country="${E(c)}" ${w?.cup?.champion?'disabled':''}`,'btn'):''}${c!=='Veltrania'&&r>=18&&p?.stage!=='finalizada'?button('🏆 JUGAR '+E(p?.stage),'sim-country-final',`data-country="${E(c)}"`,'btn gold'):''}</div></div>
<div class="grid four">${stat('Jornadas',r+'/18','Fase regular')}${stat('Clubes',28,'A y B + Segunda')}${stat('Líder anual',E(countryRows(c,'annual')[0]?.name||'—'),'Escudo de Oro')}${stat('Títulos',p?.stage==='finalizada'?'3':'0','En esta temporada')}</div>
<div class="grid two"><div class="card"><div class="eyebrow">ZONA A</div>${table(countryRows(c,'A'),'A')}</div><div class="card"><div class="eyebrow">ZONA B</div>${table(countryRows(c,'B'),'B')}</div></div><div class="card"><div class="eyebrow">ESCUDO DE ORO · TABLA ANUAL</div>${table(countryRows(c,'annual'),'annual')}</div><div class="card"><div class="eyebrow">SEGUNDA DIVISIÓN · ASCENSOS</div>${table(countryRows(c,'S'),'S')}</div>
<div class="card"><div class="between"><h2 class="h2">📰 Resultados de la Jornada ${r}</h2><span class="tag">${past.length} PARTIDOS</span></div><div class="grid two">${past.length?past.map(m=>scoreFixture(m)).join(''):'<p>Esta fecha todavía no tiene partidos disputados.</p>'}</div><div class="rule"></div><h2 class="h2">Próxima fecha ${upcoming}</h2><div class="grid two">${future.slice(0,16).map(m=>scoreFixture(m)).join('')||'<p class="muted">La fase regular ha finalizado.</p>'}</div></div>
${c!=='Veltrania'&&w?.cup?`<div class="card"><h2 class="h2">🏆 Copa Nacional de ${E(c)}</h2><p class="muted small">${E(w.cup.stage)} · Fecha ${w.cup.round} · ${w.cup.champion?'Campeón: '+E(w.cup.champion):'En disputa'}</p><div class="grid two">${w.cup.fixtures.filter(f=>f.round===w.cup.round).map(scoreFixture).join('')}</div></div>`:''}${p?.fixtures?.length?`<div class="card"><h2 class="h2">🏆 Semifinales, gran final y Recopa</h2><p class="small muted">Fase: ${E(p.stage)} · ${p.apertura?'Campeón Apertura: '+E(p.apertura):'En disputa'}</p>${p.fixtures.map(scoreFixture).join('')}</div>`:''}</div>`;}
function internationalPage(){const intl=ensureInternational(s);let status=intl?intl.champions.phase:'clasificación';const provisional=COUNTRIES.map(c=>({c,rows:countryRows(c,'annual')}));return `<div class="stack">${head('Copas de Arcalis','Dos caminos a la gloria. Todos los países compiten en el mismo continente.')}
<div class="hero stadium-photo"><div class="hero-copy"><span class="tag goldtag">CFA · CONFEDERACIÓN DE ARCALIS</span><h2>EL CONTINENTE<br><span class="gold">ES NUESTRO.</span></h2><p>Copa de Campeones: 6 directos por país + nueve repechajes. Copa Horizonte: cinco clubes de cada país. No hay selección nacional ni Mundial.</p></div></div>
${!intl?`<div class="notice">🔒 Las copas se generan automáticamente cuando las 9 primeras divisiones terminen la Jornada 18. Los cupos mostrados abajo son provisionales.</div>`:''}
<div class="grid two">${['champions','horizonte'].map(id=>{const c=intl?.[id],nm=id==='champions'?'🏆 Copa de Campeones':'✦ Copa Horizonte',groups=c?.groups||[];return `<div class="card"><div class="eyebrow">TORNEO CONTINENTAL ${s.season}</div><h2 class="h2">${nm}</h2><p class="small muted">${id==='champions'?'54 directos + 9 ganadores de repechaje · 9 grupos de 7':'45 participantes · 9 grupos de 5'}. Los 9 campeones de grupo y los 7 mejores segundos avanzan a octavos.</p><div class="controls">${button(c?.champion?'🏆 '+E(c.champion):c?'▶ SIMULAR RONDA '+c.round:'🔒 Aún no disponible','sim-intl',`data-cup="${id}" ${!c||c.champion?'disabled':''}`,'btn primary')}</div><div class="eyebrow" style="margin-top:15px">${c?'FASE: '+E(c.phase.toUpperCase()):'POR CLASIFICACIÓN'}</div>${c?.fixtures?.filter(f=>f.round===c.round&&f.phase===c.phase).slice(0,9).map(scoreFixture).join('')||''}${groups.length?`<div class="grid two" style="margin-top:12px">${groups.map(g=>`<div><div class="tag goldtag">GRUPO ${g.id}</div>${table(ranking(c.fixtures.filter(f=>f.phase==='groups'&&f.group===g.id),g.teams),'custom')}</div>`).join('')}</div>`:''}</div>`}).join('')}</div>
<div class="card"><h2 class="h2">🎟️ Clasificación por país</h2><div class="grid three">${provisional.map(({c,rows})=>`<div class="mini-country"><div class="eyebrow">${E(c)}</div><h3 class="h3">${E(rows[0]?.name||'—')}</h3><div class="tiny gold">Campeones: puestos 1.º–6.º</div><p class="small muted">7.º repechaje: ${E(rows[6]?.name||'—')}<br>Horizonte 8.º–12.º</p>${button('Abrir liga →','select-country',`data-country="${E(c)}"`,'btn sm')}</div>`).join('')}</div></div></div>`;}
function livePage(){let matches=[...s.fixtures,...Object.values(s.world||{}).flatMap(w=>w.fixtures),...s.competitions.flatMap(c=>c.fixtures)].filter(m=>played(m)&&m.events?.length).reverse();const m=matches.find(f=>f.id===ui.liveMatch)||matches[0];if(!m)return `<div class="stack">${head('Centro en vivo 2D','Se activa cuando simules un partido nuevo con acta detallada.')}<div class="notice">Las seis jornadas históricas no tienen jugadas individuales inventadas.</div></div>`;if(ui.liveMatch!==m.id){ui.liveMatch=m.id;ui.liveMinute=0;}const events=m.events.filter(e=>e.min<=ui.liveMinute),h=m.events.filter(e=>e.type==='goal'&&e.side==='home'&&e.min<=ui.liveMinute).length,a=m.events.filter(e=>e.type==='goal'&&e.side==='away'&&e.min<=ui.liveMinute).length;return `<div class="stack">${head('Centro de partido 2D','Reproducción visual del acta real del simulador. No altera un resultado ya disputado.')}
<div class="card"><label class="field"><span>Elegí un partido</span><select id="liveMatchSelect">${matches.slice(0,160).map(f=>`<option value="${E(f.id)}" ${f.id===m.id?'selected':''}>${E(f.home)} ${f.scoreH}-${f.scoreA} ${E(f.away)} · J${f.round}</option>`).join('')}</select></label></div>
<div class="live-board"><div class="eyebrow">⚽ REPETICIÓN 2D · ${E(m.competition)}</div><div class="live-score"><div>${crest(m.home)}<b>${E(m.home)}</b></div><strong>${h} : ${a}</strong><div>${crest(m.away)}<b>${E(m.away)}</b></div></div><div class="live-pitch"><div class="live-center"></div>${Array.from({length:11},(_,i)=>`<span class="pitch-player home" style="left:${8+(i%4)*11}%;top:${10+Math.floor(i/4)*39+((i%3)*4)}%"></span>`).join('')}${Array.from({length:11},(_,i)=>`<span class="pitch-player away" style="left:${52+(i%4)*11}%;top:${10+Math.floor(i/4)*39+((i%3)*4)}%"></span>`).join('')}<span class="pitch-ball" style="left:${5+(ui.liveMinute*7)%89}%;top:${17+(ui.liveMinute*17)%64}%">⚽</span></div><div class="controls" style="justify-content:center;margin-top:17px">${button('⟲ Reiniciar','live-reset','','btn')}${button(ui.playing?'⏸ Pausar':'▶ Reproducir','live-toggle','','btn primary')}${button('+ 5 MIN','live-step','','btn')}</div><label class="field" style="margin-top:10px"><span>Minuto ${ui.liveMinute}' / 90'</span><input type="range" id="liveMinuteSlider" min="0" max="90" value="${ui.liveMinute}"></label></div>
<div class="card"><h2 class="h2">Relato minuto a minuto</h2>${events.length?events.slice().reverse().map(e=>`<div class="market-event"><span class="gold">${e.min}'</span><div><b>${e.type==='goal'?'⚽ GOL':e.type==='yellow'?'🟨 Amonestación':e.type==='red'?'🟥 Expulsión':e.type==='injury'?'🚑 Lesión':e.type==='var'?'📺 VAR':'🔁 Cambio'}</b><div class="muted small">${E(e.side==='home'?m.home:m.away)} · ${E(e.p1Name||'')}${e.p2Name?' / '+E(e.p2Name):''}</div></div></div>`).join(''):'<div class="notice">Puesta en marcha. El árbitro está listo para comenzar.</div>'}</div>${ui.liveMinute===90?`<div class="notice">⏱️ FINAL · ${E(m.home)} ${m.scoreH}-${m.scoreA} ${E(m.away)}. ${button('📰 Leer periódico','match',`data-id="${E(m.id)}"`,'btn sm')}</div>`:''}</div>`;}
function pressPage(){const name=ui.team,t=club(name);ensureEcosystem(s);const q=PRESS_QUESTIONS[(s.ecosystem.pressConferenceCount||0)%PRESS_QUESTIONS.length];return `<div class="stack">${head('Sala de prensa','Tu relación con medios, hinchas y jugadores influye en la moral del club.')}
<div class="press-hero stadium-photo"><span class="tag goldtag">🎙️ CONFERENCIA DE PRENSA</span><h2>LA PALABRA TAMBIÉN JUEGA.</h2><p>${E(t.coach)} · ${E(t.name)}</p></div><div class="card"><label class="field"><span>Equipo</span><select id="manageClubV4">${Object.values(s.teams).map(v=>`<option ${v.name===name?'selected':''}>${E(v.name)}</option>`).join('')}</select></label><h2 class="h2" style="margin-top:17px">Periodista: «${E(q)}»</h2><div class="grid two">${[['calm','Con serenidad','No cambiar nada por la presión'],['passion','Con exigencia','La camiseta requiere sacrificio'],['defend','Defender al vestuario','Respaldo a mis jugadores'],['critic','Criticar el rendimiento','Hay cosas por corregir']].map(([id,n,subtitle])=>`<button class="response" data-action="press-answer" data-answer="${id}"><b>${n}</b><span>${subtitle}</span></button>`).join('')}</div></div>
<div class="card"><h2 class="h2">🗞️ Redacciones deportivas</h2><div class="grid three">${MEDIA.map(m=>`<div class="mini-country"><h3 class="h3">${E(m.name)}</h3><p class="muted small">${E(m.focus)}</p>${button('Leer noticias →','switch-medium',`data-medium="${m.id}"`,'btn sm')}</div>`).join('')}</div><h3 class="h3">${E(ui.media||'Heraldo')} · Titulares</h3>${s.news.filter(a=>ui.media==='Radar'?a.category==='Mercado':ui.media==='Tribuna'?['LSV','Arcalis','Directivas','Prensa','Afición'].includes(a.category):true).slice(0,13).map(newsCard).join('')}</div></div>`;}
function fansPage(){const t=club(ui.team);ensureEcosystem(s);const rivals=rivalsOf(s,t.name);return `<div class="stack">${head('Aficiones y clásicos','El fútbol también se vive en las tribunas. Los seguidores reaccionan a cada resultado.')}
<div class="supporter-banner" style="--fan-tint:${E(t.primary)}"><span>TRIBUNA DE NO­VERIA</span><strong>${E(t.fans)} · ${E(t.name)}</strong><small>Capacidad ${n(t.capacity)} · Ambiente ${t.supporters.mood}/99</small></div><div class="card"><label class="field"><span>Elegí un club</span><select id="manageClubV4">${Object.values(s.teams).map(v=>`<option ${v.name===ui.team?'selected':''}>${E(v.name)}</option>`).join('')}</select></label></div><div class="grid four">${stat('Ánimo afición',t.supporters.mood+'/99','Varía con los resultados')}${stat('Capacidad',n(t.capacity),'Aforo oficial')}${stat('Última asistencia',n(t.supporters.lastAttendance),'Personas en casa')}${stat('Acumulada',n(t.supporters.attendance),'Taquillas') }</div>
<div class="card"><h2 class="h2">🔥 Historial de enfrentamientos</h2><div class="notice">Los clásicos tradicionales permanecen. Nuevas rivalidades pueden fortalecerse por partidos decisivos y repeticiones históricas.</div>${rivals.length?rivals.map(r=>`<div class="market-event"><strong>${E(r.opponent)}</strong><span class="muted small">PJ ${r.games} · ${r.w}G ${r.d}E ${r.l}P · GF ${r.gf} GC ${r.gc}</span></div>`).join(''):'<p class="muted">Aún no hay enfrentamientos detallados para este club en esta partida.</p>'}</div></div>`;}
function academyPage(){const t=club(ui.team),y=inspectAcademy(s,ui.team);return `<div class="stack">${head('Cantera y formación','Promesas sub-20, entrenamientos, ascensos y partidos juveniles.')}
<div class="card"><label class="field"><span>Escoger club</span><select id="manageClubV4">${Object.values(s.teams).map(v=>`<option ${v.name===ui.team?'selected':''}>${E(v.name)}</option>`).join('')}</select></label><div class="between" style="margin-top:15px"><div><h2 class="h2">Academia de ${E(t.name)}</h2><p class="muted small">Instalaciones nivel ${t.facility.academy}/5 · ${y.length} promesas · ${E(t.budget.toFixed(2))} M VLR</p></div><div class="controls">${button('🏋 Entrenar (0,10 M)','youth-train','','btn primary')}${button('🏗 Mejorar instalaciones','facility-upgrade','data-facility="academy"','btn')}</div></div></div><div class="grid three">${y.map(p=>`<div class="card"><div class="eyebrow">${E(p.pos)} · ${p.age} años · ${E(p.nationality)}</div><h3 class="h3">${E(p.name)}</h3><div class="between"><strong class="gold">OVR ${p.ovr}</strong><span class="tag">POT ${p.pot}</span></div><div style="margin-top:12px">${button('⬆ Subir al primer equipo','youth-promote',`data-id="${E(p.id)}"`,'btn primary sm')}</div></div>`).join('')}</div><div class="card"><h2 class="h2">⚽ Amistosos sub-20</h2><p class="muted small">Las canteras pueden medir el desarrollo de sus juveniles. Los resultados se registran por separado de Primera.</p>${button('Simular amistoso juvenil','youth-friendly','','btn')} ${button('🏆 Jugar Liga Sub-20 de '+E(t.country),'youth-league','','btn primary')}${(s.ecosystem?.youthResults||[]).slice(0,5).map(r=>`<p class="muted small">${E(r.a)} ${r.home}-${r.away} ${E(r.b)}</p>`).join('')}</div></div>`;}
function stadiumPage(){const t=club(ui.team);return `<div class="stack">${head('Estadios, economía e instalaciones','La infraestructura construye el futuro de cada institución.')}
<div class="stadium-band stadium-photo"><div><span class="tag goldtag">CASA DE ${E(t.name.toUpperCase())}</span><h2>🏟️ ${E(t.stadium)}</h2><p>Ciudad: ${E(t.city)} · Capacidad actual: ${n(t.capacity)} aficionados</p></div></div><div class="card"><label class="field"><span>Club</span><select id="manageClubV4">${Object.values(s.teams).map(v=>`<option ${v.name===ui.team?'selected':''}>${E(v.name)}</option>`).join('')}</select></label></div><div class="grid four">${stat('Estadio',t.facility.stadium+'/5','+5.000 plazas por mejora')}${stat('Cantera',t.facility.academy+'/5','Talentos')}${stat('Sanidad',t.facility.medical+'/5','Preparación')}${stat('Ojeadores',t.facility.scouting+'/5','Captación')}</div><div class="card"><h2 class="h2">💰 Presupuesto: ${Number(t.budget||0).toFixed(2)} millones de VLR</h2><div class="grid two">${[['stadium','🏟️ Ampliar estadio','2.5'],['academy','🌱 Mejorar cantera','1.35'],['medical','🚑 Mejorar enfermería','1.1'],['scouting','🔎 Mejorar ojeadores','0.8']].map(([key,label,cost])=>`<button class="response" data-action="facility-upgrade" data-facility="${key}"><b>${label}</b><span>Inversión: ${cost} M VLR · Nivel ${t.facility[key]}/5</span></button>`).join('')}</div></div></div>`;}
function awardsPage(){const c=ui.country||'Veltrania';const roster=countryRows(c,'annual').map(r=>r.name),a=seasonAwards(s,c,roster);return `<div class="stack">${head('Premios y leyendas','Jugadores y entrenadores escriben el palmarés individual.')}
<div class="card"><label class="field"><span>País</span><select id="countrySelect">${COUNTRIES.map(x=>`<option ${x===c?'selected':''}>${E(x)}</option>`).join('')}</select></label><div class="notice">Las estadísticas individuales empiezan desde la Jornada 7 del Apertura 2026. No inventamos goleadores de las seis fechas históricas.</div></div><div class="grid two">${a.length?a.map(v=>`<div class="card trophy-award"><div class="gold" style="font-size:31px">🏆</div><span class="eyebrow">${E(v.title)}</span><h2 class="h2">${E(v.player.name)}</h2><p>${E(v.player.club)} · ${v.player.goals} goles · ${v.player.assists} asistencias</p></div>`).join(''):'<div class="notice">Todavía no hay estadísticas de jugadores para estos premios.</div>'}</div><div class="card"><h2 class="h2">Gala anual y archivo de premios</h2>${(s.ecosystem?.awardHistory||[]).filter(x=>x.country===c).map(a=>`<div><h3>Apertura ${a.season}</h3>${a.results.map(z=>`<p>${E(z.title)}: ${E(z.player)} (${E(z.club)})</p>`).join('')}</div>`).join('')||'<p class="muted">La primera gala tendrá lugar al cierre del campeonato.</p>'}</div></div>`;}
function museumPage(){const honours=s.honours||[];return `<div class="stack">${head('Museo del fútbol','Palmarés, vitrinas, finales inolvidables y récords que quedarán para siempre.')}
<div class="hero stadium-photo"><div class="hero-copy"><span class="tag goldtag">MUSEO DE LA HISTORIA DE NOVERIA</span><h2>LOS TÍTULOS<br><span class="gold">SON ETERNOS.</span></h2><p>Nadie comenzó con trofeos. Toda copa nace de un partido que alguien tuvo que ganar.</p></div></div><div class="grid four">${stat('Campeonatos',honours.length,'Palmarés registrado')}${stat('Países',9,'Arcalis')}${stat('Clubes',Object.keys(s.teams).length,'Noveria')}${stat('Temporadas',s.season-2025,'Desde 2026')}</div><div class="card"><h2 class="h2">🏆 Galería de campeones</h2>${honours.length?honours.slice().reverse().map(h=>`<div class="market-event"><strong>${E(h.winner)}</strong><span class="tag">🏆 ${E(h.title)} · ${E(h.season)}</span></div>`).join(''):'<div class="empty">El primer campeón todavía está por proclamarse.</div>'}</div><div class="card"><h2 class="h2">📜 Archivo de temporadas</h2>${s.archive.map(a=>`<div class="market-event"><strong>Apertura ${a.season}</strong><span class="muted small">Escudo de Oro: ${E(a.annual?.[0]?.name||'—')}</span></div>`).join('')||'<p class="muted small">Aún no hay temporadas anteriores.</p>'}</div></div>`;}
function careerPage(){ensureEcosystem(s);const c=s.career,offers=c.offers||[];return `<div class="stack">${head('Carrera de entrenador','Construí tu propia historia: ofertas, reputación, cambios de club y resultados.')}
<div class="hero stadium-photo"><div class="hero-copy"><span class="tag goldtag">MODO CARRERA</span><h2>LA PRÓXIMA LEYENDA<br><span class="gold">SOS VOS.</span></h2><p>Tu carrera no se limita a un club. Podés empezar en Segunda y terminar compitiendo por Arcalis.</p></div></div><div class="grid three">${stat('Club actual',E(s.managedClub),'Modo '+E(s.mode))}${stat('Reputación',c.reputation+'/99','Prestigio')}${stat('Equipos dirigidos',c.history.length+1,'Trayectoria')}</div><div class="card"><h2 class="h2">💼 Despacho personal</h2><form id="careerForm" class="form"><label class="field"><span>Tu nombre de entrenador</span><input class="input" name="coachName" value="${E(c.name)}" maxlength="60"></label><button class="btn primary" type="submit">Guardar perfil del DT</button></form><div class="controls" style="margin-top:18px">${button('Buscar ofertas de empleo','career-offers','','btn gold')}${button('Ver mi club','go-office',`data-name="${E(s.managedClub)}"`,'btn')}</div></div><div class="card"><h2 class="h2">📨 Ofertas de otros clubes</h2><div class="grid two">${offers.length?offers.map(x=>`<div class="mini-country"><div class="eyebrow">OFERTA · ${E(x.country)}</div><h3 class="h3">${E(x.club)}</h3><p class="small muted">Contrato ofrecido · ${x.salary} M VLR por año</p>${button('Aceptar cargo','career-job',`data-club="${E(x.club)}"`,'btn primary')}</div>`).join(''):'<p class="muted">Buscá ofertas para conocer los clubes interesados.</p>'}</div></div><div class="card"><h2 class="h2">📖 Trayectoria</h2>${c.history.map(h=>`<div class="market-event"><b>${E(h.from)} → ${E(h.to)}</b><span>${h.season}</span></div>`).join('')||'<p class="muted">Toda gran carrera tiene un principio.</p>'}</div></div>`;}

function newsPage(){return `<div class="stack">${head('Periódico de Noveria','Goles, sorpresas, mercados, despidos y cada crónica que nace del simulador.')}
<div class="grid two"><div class="card"><div class="eyebrow">EL HERALDO DE NOVERIA</div><h2 class="h2">Archivo periodístico</h2><p class="muted small">Cada partido simulado desde la próxima jornada genera su propia edición: resumen, minuto a minuto, goleadores, tarjetas, estadísticas y alineaciones.</p></div>${unionPanel()}</div><div class="articles">${s.news.map(newsCard).join('')}</div></div>`;}
function historyPage(){const summ=leagueSummary(s);return `<div class="stack">${head('Palmarés y partida','Los títulos comienzan en cero. Todo lo que suceda quedará registrado.')}
<div class="grid three">${stat('Temporada',s.season,'Apertura nacional')}${stat('Títulos entregados',s.honours.length,'Palmarés oficial')}${stat('Partidos',summ.matches,'Marcadores importados + nuevos')}</div><div class="grid two"><div class="card"><h2 class="h2">Vitrina de campeones</h2>${s.honours.length?s.honours.map(h=>`<div class="between" style="padding:12px 0;border-bottom:1px solid var(--line)"><div><span class="gold tiny">${E(h.title)}</span><div class="bold">${E(h.winner)}</div></div><span class="tag">${E(h.season)}</span></div>`).join(''):'<div class="empty">🏆<strong>Todavía nadie ha levantado un trofeo.</strong> La primera temporada está escribiéndose.</div>'}<div class="rule"></div><h3 class="h3">Mercado</h3>${button('💰 Ir al centro de pases','nav','data-target="mercado"','btn sm')}${s.transfers.length?s.transfers.slice(0,12).map(t=>`<p class="small muted">${E(t.player)}: ${E(t.from)} → ${E(t.to)} ${t.fee!==undefined?'· '+Number(t.fee).toFixed(2)+' M VLR':''}</p>`).join(''):'<p class="muted small">No se han registrado fichajes.</p>'}</div><div class="card"><h2 class="h2">Guardar o recuperar la partida</h2><p class="muted small">Tu partida se guarda automáticamente en <b>este navegador y dispositivo</b>, con una copia adicional en la base local cuando está disponible. No requiere cuenta. Para usar otro celular, navegador o computadora, exportá e importá el JSON; GitHub aloja el código, <b>no sincroniza las partidas</b>.</p><div class="save-dashboard"><div class="save-indicator" data-save-status>${E(saveStatus.message)}</div><div class="tiny muted">Última actualización: <span data-save-time>${E(readableSaveTime(saveStatus.savedAt))}</span></div><p class="small muted">Se guarda automáticamente al simular jornadas, fichar, cambiar DT, editar uniformes y avanzar temporadas. Al volver al mismo enlace de GitHub Pages con este navegador, la partida se recupera.</p></div><div class="stack">${button('💾 Guardar ahora','save-now','','btn green')}<div class="controls">${button('🛟 Crear punto de recuperación','checkpoint','','btn sm')}${button('↶ Restaurar punto seguro','checkpoint-restore','','btn sm')}${button('🔒 Proteger almacenamiento','protect-save','','btn sm')}</div>${button('↓ Descargar copia JSON','export','','btn primary')}<label class="field"><span>Restaurar una partida JSON</span><input class="input" id="importFile" type="file" accept="application/json,.json"></label>${button('⚠ Restablecer el universo','reset','','btn danger')}</div><div class="rule"></div><div class="notice">El progreso se guarda localmente. Exportá un JSON antes de cambiar de temporada para conservar una copia segura.</div></div></div>
 <div class="card"><div class="eyebrow">ARCHIVO DE LA FEDERACIÓN VELTRANA</div><h2 class="h2">Temporadas anteriores</h2>${s.archive?.length?s.archive.map(a=>`<div class="market-event"><div><strong>🏆 Apertura ${a.season}</strong><div class="muted small">Escudo anual: ${E(a.annual[0].name)} · Ascendieron: ${E(a.promoted.join(', '))}</div></div>${button('Ver temporada','history-season',`data-id="${a.season}"`,'btn sm')}</div>`).join(''):'<p class="muted small">Aún no hemos cerrado la primera temporada de nuestra historia.</p>'}</div>
 <div class="card"><h2 class="h2">🔄 Continuar hacia una nueva temporada</h2><p class="muted small">Al terminar final y Recopa, y cerrar el mercado, se activará el inicio de la próxima temporada: dos ascensos, dos descensos, jugadores un año mayores, presupuestos actualizados y calendario nuevo. Los títulos y marcadores anteriores quedan en el archivo histórico.</p>${button('🚀 Iniciar Apertura '+(s.season+1),'next-season',`${s.postseason?.stage==='finalizada'&&s.market.status==='closed'?'':'disabled'}`,'btn primary')}
 ${s.postseason?.stage==='finalizada'&&s.market.status==='open'?'<p class="notice">Primero tenés que cerrar la ventana de fichajes.</p>':''}</div></div>`;}
function render(){let pages={inicio:dashboard,jornadas:matchesPage,resultados:resultsPage,clasificaciones:standingsPage,clubes:clubsPage,jugadores:playersPage,uniformes:kitsPage,directivas:officePage,mercado:marketPage,fasefinal:postseasonPage,copa:cupPage,torneos:compPage,mundo:worldPage,noticias:newsPage,historia:historyPage,pais:countryPage,arc:internationalPage,vivo:livePage,prensa:pressPage,aficion:fansPage,cantera:academyPage,estadios:stadiumPage,premios:awardsPage,museo:museumPage,carrera:careerPage};if(!pages[ui.page])ui.page='inicio';$('app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-icon">⚽</div><div><strong>NOVERIA</strong><small>FOOTBALL UNIVERSE</small></div></div><div class="navlabel">UNIVERSO</div><nav class="nav">${menu.map(([id,icon,label])=>`<button class="${ui.page===id?'active':''}" data-action="nav" data-target="${id}"><span class="emoji">${icon}</span>${label}</button>`).join('')}</nav><div class="sidebar-foot"><div class="eyebrow">MI CLUB</div><strong>🔴⚫ Unión Popular Aurena</strong><div style="margin-top:8px">Seguimiento especial sin favoritismos deportivos.</div><div class="rule"></div><div data-save-status class="save-status">${E(saveStatus.message)}</div><div class="muted tiny" data-save-time>${E(readableSaveTime(saveStatus.savedAt))}</div></div></aside><main class="main">${pages[ui.page]()}</main></div><nav class="mobileNav">${[['inicio','◈','Inicio'],['jornadas','⚽','Jugar'],['clasificaciones','▥','Tablas'],['clubes','⬡','Clubes'],['MORE','☷','Más']].map(([id,icon,label])=>`<button class="${ui.page===id?'on':''}" data-action="${id==='MORE'?'menu':'nav'}" data-target="${id}"><span class="emoji">${icon}</span>${label}</button>`).join('')}</nav>`;}
function modal(title,body){$('overlay').innerHTML=`<div class="backdrop" data-action="close-overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="modalhead"><h2>${E(title)}</h2><button class="close" data-action="close">✕</button></div><div class="modalbody">${body}</div></div></div>`;document.body.style.overflow='hidden';}
function close(){ $('overlay').innerHTML='';document.body.style.overflow='';}
function lookupMatch(id){return [...s.fixtures,...s.cup.fixtures,...(s.postseason?.fixtures||[]),...s.competitions.flatMap(c=>c.fixtures),...Object.values(s.world||{}).flatMap(w=>[...w.fixtures,...(w.cup?.fixtures||[]),...(w.postseason?.fixtures||[]),...(w.archive||[]).flatMap(a=>[...(a.fixtures||[]),...(a.postseason?.fixtures||[])])]),...(s.international?.champions?.fixtures||[]),...(s.international?.horizonte?.fixtures||[]),...(s.archive||[]).flatMap(a=>[...(a.fixtures||[]),...(a.postseason?.fixtures||[]),...(a.cup?.fixtures||[])])].find(m=>m.id===id)}
function paper(m){const home=club(m.home),away=club(m.away);if(!played(m)){modal('Ficha del encuentro',`<div class="card"><h2>${E(m.home)} vs. ${E(m.away)}</h2><p class="muted">${E(home.stadium)} · Jornada ${m.round}</p><p>Este encuentro aún no se ha disputado. Simulá su jornada para generar el periódico.</p></div>`);return}
 const src=m.legacy,stats=m.stats,eh=(m.events||[]),hPlayers=m.lineupDetails?.home||m.lineups?.home?.map(id=>home.players.find(p=>p.id===id)).filter(Boolean)||[],aPlayers=m.lineupDetails?.away||m.lineups?.away?.map(id=>away.players.find(p=>p.id===id)).filter(Boolean)||[];
 const headline=src?`${m.home} ${m.scoreH} - ${m.scoreA} ${m.away}`:m.headline;
 const eventText=ev=>ev.type==='goal'?`⚽ GOL de ${ev.p1Name}${ev.p2Name?` · asistencia de ${ev.p2Name}`:''}`:ev.type==='yellow'?`🟨 Amonestado ${ev.p1Name}`:ev.type==='red'?`🟥 Expulsado ${ev.p1Name}`:ev.type==='injury'?`🚑 Lesión de ${ev.p1Name}`:`🔄 Cambio: sale ${ev.p1Name}, entra ${ev.p2Name}`;
 const metric=(name,a,b,percent=false)=>`<div class="paperstat"><b>${a}${percent?'%':''}</b><span>${E(name)}</span><b>${b}${percent?'%':''}</b></div>`;
 const lines=(players,team)=>`<div><div style="font-weight:800;margin-bottom:7px">${E(team.name)}</div>${players.map(p=>`<div class="event" style="grid-template-columns:24px 1fr;gap:7px"><b>${p.number}</b><span>${E(p.name)} · ${p.pos} <b>${p.form.toFixed(1)}</b></span></div>`).join('')}</div>`;
 const summary=src?'Este encuentro pertenece al archivo de las seis primeras jornadas, disputadas en nuestra historia antes de la creación de la aplicación. Se conserva el resultado original sin inventar goleadores, estadísticas ni acontecimientos que no fueron registrados.':m.summary;
 const date=m.competition==='LSV'?'LIGA SUPREMA VELTRANA':m.competition==='LPV'?'LIGA DE PLATA':m.competition==='CUP'?'COPA DE LAS PROVINCIAS':m.competition==='POST'?'FASE FINAL · LIGA SUPREMA':'TORNEO ESPECIAL';
 modal('El Heraldo de Noveria · Crónica de partido',`<div class="reportwrap"><div class="noPrint between" style="padding:0 0 15px"><span class="muted small">Crónica lista para imprimir o guardar como PDF</span>${button('🖨 Imprimir periódico','print','','btn sm')}</div><article class="newspaper"><div class="paperbrand">EL HERALDO DE NOVERIA<br><span style="font-size:10px;letter-spacing:.13em">EDICIÓN DEPORTIVA · APERTURA ${s.season}</span></div><div class="paperSub" style="margin-top:16px">${E(date)} · JORNADA ${m.round} · ${E(home.stadium)} · ${E(home.city)}</div><h1>${E(headline)}</h1><div class="paper-atmosphere"></div><div class="paperSub" style="text-align:left">${src?'Archivo oficial de resultados':'Crónica del encuentro · Datos generados por el motor de simulación'}</div><div class="paperScore"><span>${E(m.home)}</span><strong>${m.scoreH} — ${m.scoreA}</strong><span>${E(m.away)}</span></div><p style="font-size:17px;font-weight:600">${E(summary)}</p>${m.penalties?`<p style="font-weight:bold">La eliminatoria se decidió tras tiempo extra y penales: ${E(m.penalties)}.</p>`:''}${!src?`<p>Una tarde de fútbol que quedará en los registros de la primera historia futbolística de Noveria. Cada detalle, desde las oportunidades hasta las decisiones tácticas, influye en lo que sucede sobre el césped.</p><h3>Minuto a minuto</h3><div class="timeline">${eh.map(ev=>`<div class="event"><strong>${ev.min}'</strong><span>${E(eventText(ev))} <i>(${ev.side==='home'?E(home.name):E(away.name)})</i></span></div>`).join('')}</div><h3>Así se jugó el partido</h3><div class="paperstats">${metric('Posesión',stats.posH,stats.posA,true)}${metric('Tiros',stats.shotsH,stats.shotsA)}${metric('Tiros al arco',stats.onH,stats.onA)}${metric('Córners',stats.cornersH,stats.cornersA)}${metric('Faltas',stats.foulsH,stats.foulsA)}${metric('Goles esperados',stats.xgH,stats.xgA)}</div><h3>Alineaciones y calificaciones</h3><div class="paperstats">${lines(hPlayers,home)}${lines(aPlayers,away)}</div><h3>El duelo desde el banquillo</h3><p>El entrenador ${E(m.coachAtKickoff?.home||home.coach)} presentó a ${E(home.name)} con un ${E(m.coachAtKickoff?.homeFormation||home.formation)} y un planteamiento de ${E((m.coachAtKickoff?.homeTactic||home.tactic).toLowerCase())}. Enfrente, ${E(m.coachAtKickoff?.away||away.coach)} apostó por el ${E(m.coachAtKickoff?.awayFormation||away.formation)} y ${E((m.coachAtKickoff?.awayTactic||away.tactic).toLowerCase())}.</p>`:`<div style="background:#e1dccf;padding:16px;margin:22px 0;font:13px Arial,sans-serif"><strong>ARCHIVO HISTÓRICO — MARCADOR VERIFICADO</strong><div style="margin-top:7px">Sin acta de goleadores o estadísticas de futbolistas. Para no falsear la historia, esos datos individuales solo se crean desde las jornadas nuevas simuladas por la aplicación.</div></div>`}<div style="border-top:3px double #505a62;margin-top:25px;padding-top:12px;font:11px Arial,sans-serif">NOVERIA FOOTBALL UNIVERSE · Un mundo completamente ficticio · Temporada ${s.season}</div></article></div>`);
}
function clubModal(name){const t=club(name);if(!t)return;const sm=s.fixtures.filter(f=>played(f)&&[f.home,f.away].includes(name));let w=0,d=0,l=0;for(const x of sm){const scored=x.home===name?x.scoreH:x.scoreA,conceded=x.home===name?x.scoreA:x.scoreH;if(scored>conceded)w++;else if(scored===conceded)d++;else l++;}
 modal(t.name,`<div class="stack"><div class="club-heading">${crest(t.name)}<div class="grow"><div class="eyebrow">${E(t.country)} · ${t.division==='LSV'?'Primera':t.division==='LPV'?'Segunda':'Club internacional'}</div><h2 style="font-size:27px;margin:4px 0">${E(t.name)}</h2><div class="muted small">${E(t.nickname)} · Fundado en ${t.year}</div></div></div><div class="supporter-banner stadium-photo" style="--fan-tint:${E(t.primary)}"><span>LA HINCHADA · ${E(t.fans)}</span><strong>${E(t.stadium)}</strong><small>${E(t.city)} · ${n(t.capacity)} espectadores</small></div><div class="grid four">${statBare('OVR',t.rating)}${statBare('PJ oficiales',sm.length)}${statBare('Victorias',w)}${statBare('Trofeos',t.trophies.length)}</div><div class="grid two"><div class="card inner"><h3 class="h3">Identidad y afición</h3><p class="small">${E(t.identity)}</p><p class="small"><b>Hinchada:</b> ${E(t.fans)}</p><p class="small"><b>Estadio:</b> ${E(t.stadium)}, capacidad ${n(t.capacity)}</p><p class="small"><b>Ciudad:</b> ${E(t.city)}</p><p class="small"><b>Colores:</b> <span style="color:${E(t.primary)}">●</span> <span style="color:${E(t.secondary)}">●</span></p></div><div class="card inner"><h3 class="h3">Directiva</h3><p class="small"><b>Presidente:</b> ${E(t.president)}</p><p class="small"><b>DT:</b> ${E(t.coach)}</p><p class="small"><b>Director:</b> ${E(t.director)}</p><p class="small"><b>Táctica:</b> ${E(t.formation)} · ${E(t.tactic)}</p><p class="small"><b>Presupuesto:</b> ${t.budget.toFixed(1)} millones de VLR</p></div></div><h3 class="h3">Uniformes oficiales</h3><div class="kits">${t.kits.map((_,i)=>`<div class="kitbox">${kitSVG(t,i)}<span class="tag">${['LOCAL','VISITANTE','TERCERO'][i]}</span></div>`).join('')}</div><h3 class="h3">Plantilla y estadísticas</h3><div class="tablewrap"><table><thead><tr><th>#</th><th style="text-align:left">Jugador</th><th>POS</th><th>Edad</th><th>OVR</th><th>POT</th><th>PJ</th><th>Goles</th></tr></thead><tbody>${t.players.map(p=>`<tr><td>${p.number}</td><td class="clubname" data-action="player" data-player="${p.id}" data-name="${E(t.name)}">${E(p.name)}</td><td>${p.pos}</td><td>${p.age}</td><td>${p.ovr}</td><td>${p.pot}</td><td>${p.apps}</td><td>${p.goals}</td></tr>`).join('')}</tbody></table></div><div class="between"><h3 class="h3">Palmarés</h3>${button('⚙ Gestionar club','go-office',`data-name="${E(name)}"`,'btn sm')}</div>${t.trophies.length?t.trophies.map(x=>`<div class="tag goldtag">🏆 ${E(x)}</div>`).join(''):'<div class="muted small">Sin títulos en el palmarés.</div>'}</div>`);
}
function playerModal(id,name){const t=club(name),p=t?.players.find(x=>String(x.id)===String(id));if(!p)return;modal(p.name,`<div class="stack"><div class="between"><div><div class="eyebrow">FICHA DE JUGADOR</div><h2 style="font-size:30px;margin:3px 0">${E(p.name)}</h2><div class="muted">${E(t.name)} · ${E(p.nationality)}</div></div><div class="scorebox" style="font-size:30px;color:var(--gold)">${p.ovr}</div></div><div class="grid four">${statBare('POS',p.pos)}${statBare('Edad',p.age)}${statBare('Potencial',p.pot)}${statBare('Valor',n(p.value)+' VLR')}</div><div class="card"><h2 class="h2">Estadísticas acumuladas</h2><div class="grid four">${statBare('Partidos',p.apps)}${statBare('Goles',p.goals)}${statBare('Asistencias',p.assists)}${statBare('Amarillas',p.yellows)}${statBare('Rojas',p.reds)}${statBare('Lesiones',p.injuries)}${statBare('Baja pendiente',(p.outGames||0)+' partidos')}${statBare('Contrato',(p.contractYears||'—')+' años')}${statBare('Forma',p.form+'/10')} ${statBare('Dorsal','#'+p.number)}</div></div><div class="notice">Las estadísticas individuales comienzan con las fechas simuladas en la app. No se inventan goleadores de las primeras seis jornadas.</div></div>`)}
function coachModal(name){const t=club(name);modal('Directiva · '+name,`<div class="stack"><div class="notice">El DT actual es <strong>${E(t.coach)}</strong>. Al cambiarlo se publica una noticia y se registra la destitución. Esto no garantiza resultados positivos.</div><form class="form" id="coachForm"><input type="hidden" name="club" value="${E(name)}"><label class="field"><span>Nombre del nuevo entrenador</span><input class="input" name="coach" maxlength="65" required placeholder="Ej. Marcos Valcera"></label><button class="btn danger" type="submit">Confirmar destitución y nuevo DT</button></form></div>`)}
function showNews(id){const a=s.news.find(n=>n.id===id);if(a?.related){const m=lookupMatch(a.related);if(m){paper(m);return}}if(a)modal(a.title,`<div class="eyebrow">${E(a.category)} · ${E(a.date)}</div><h2 style="font-size:27px">${E(a.title)}</h2><p>${E(a.description)}</p>`)}
function onAction(el){let action=el.dataset.action;if(!action)return;switch(action){
case 'select-country':ui.country=el.dataset.country||'Veltrania';nav('pais');break;
case 'sim-country':{try{const c=el.dataset.country||ui.country;const result=simulateCountryRound(s,c);save();ui.country=c;toast('⚽ '+c+' · Jornada '+result.round+' completada');reportResults(result.round,c+' · Jornada '+result.round,result.matches.map(f=>f.id));}catch(error){toast('⚠ '+error.message)}break;}
case 'sim-country-final':{try{const c=el.dataset.country||ui.country;const results=simulateCountryFinalRound(s,c);save();reportResults(null,'Finales · '+c,results.map(f=>f.id));}catch(error){toast('⚠ '+error.message)}break;}
case 'sim-country-cup':{try{const country=el.dataset.country;const games=simulateNationalCupRound(s,country);save();reportResults(null,'Copa Nacional · '+country,games.map(m=>m.id));}catch(e){toast('⚠ '+e.message)}break;}
case 'sim-intl':{try{const c=el.dataset.cup;const matches=simulateInternationalStep(s,c);save();reportResults(null,c==='champions'?'Copa de Campeones':'Copa Horizonte',matches.map(m=>m.id));}catch(error){toast('⚠ '+error.message)}break;}
case 'live-match':ui.liveMatch=el.dataset.id;ui.liveMinute=0;nav('vivo');break;
case 'live-toggle':{if(ui.playing){stopLive();render();break;}ui.playing=true;clearInterval(liveTimer);liveTimer=setInterval(()=>{if(ui.page!=='vivo'){stopLive();return;}ui.liveMinute=Math.min(90,ui.liveMinute+3);if(ui.liveMinute>=90)stopLive();render()},420);render();break;}
case 'live-step':stopLive();ui.liveMinute=Math.min(90,ui.liveMinute+5);render();break;
case 'live-reset':stopLive();ui.liveMinute=0;render();break;
case 'press-answer':try{answerPress(s,ui.team,'Conferencia',el.dataset.answer);save();toast('🎙️ Declaraciones publicadas');render()}catch(e){toast(e.message)}break;
case 'switch-medium':ui.media=el.dataset.medium;nav('prensa');break;
case 'youth-train':try{const result=youthTrain(s,ui.team);save();toast('🌱 Mejoraron: '+result.length+' promesas');render()}catch(e){toast(e.message)}break;
case 'youth-promote':try{const p=promoteProspect(s,ui.team,el.dataset.id);save();toast('⭐ '+p.name+' debutará en el plantel');render()}catch(e){toast(e.message)}break;
case 'youth-league':{try{const result=simulateYouthLeagueRound(s,club(ui.team).country);save();toast('🏆 Liga Sub-20: '+result.length+' partidos de cantera');render()}catch(e){toast('⚠ '+e.message)}break;}
case 'youth-friendly':try{const other=Object.keys(s.teams).filter(t=>t!==ui.team)[Math.floor(Math.random()*30)];const result=createYouthMatch(s,ui.team,other);save();toast('⚽ Sub-20: '+result.home+'-'+result.away);render()}catch(e){toast(e.message)}break;
case 'facility-upgrade':try{const v=upgradeFacility(s,ui.team,el.dataset.facility);save();toast('🏟️ Mejora instalada · nivel '+v.level);render()}catch(e){toast(e.message)}break;
case 'career-offers':careerOffers(s);save();render();break;
case 'career-job':try{acceptCareerJob(s,el.dataset.club);ui.team=s.managedClub;save();toast('🧑‍💼 Nuevo club: '+s.managedClub);render()}catch(e){toast(e.message)}break;
case 'nav':nav(el.dataset.target);break;case 'save-now':{save();toast('💾 Verificando guardado local…');break;}case 'checkpoint':{createCheckpoint(s).then(()=>toast('🛟 Punto seguro creado en este dispositivo')).catch(()=>toast('⚠ No se pudo crear el punto seguro. Exportá JSON.'));break;}case 'checkpoint-restore':{if(!confirm('¿Recuperar el último punto seguro? Se reemplazará tu progreso actual. Podés descargar un JSON antes.'))break;getCheckpoint(isSaveValid).then(record=>{if(!record){toast('Todavía no hay un punto de recuperación');return;}s=ensureMarket(record.state);save();ui.round=Math.min(18,getLeagueNextRound(s));toast('↶ Punto seguro recuperado');nav('inicio');}).catch(()=>toast('No se pudo leer el punto seguro'));break;}case 'protect-save':{protectStorage().then(result=>toast(!result.available?'Este navegador no permite solicitar almacenamiento persistente':result.granted?'🔒 ¡Almacenamiento protegido!':'El navegador no concedió protección adicional. Podés usar el JSON.')).catch(()=>toast('No se pudo solicitar protección'));break;}case 'menu':modal('Todas las secciones',`<div class="grid two">${menu.map(([id,icon,label])=>`<button class="btn" data-action="modal-nav" data-target="${id}">${icon} ${E(label)}</button>`).join('')}</div>`);break;case 'modal-nav':close();nav(el.dataset.target);break;case 'table':ui.table=el.dataset.id;nav('clasificaciones');break;case 'simulate-league':{const next=getLeagueNextRound(s);if(next>18)return;let res=simulateLeagueRound(s);catchUpCountries(s,res.round);if(res.round===18){ensureInternational(s);for(const c of COUNTRIES)registerAwards(s,c,countryRows(c,'annual').map(r=>r.name));}save();ui.round=res.round;toast(`⚽ Jornada ${res.round} completada · ${res.matches.length} partidos`);reportResults(res.round,'Jornada '+res.round,res.matches.map(m=>m.id));break;}case 'simulate-post':{try{let games=simulatePostseasonRound(s);save();toast('🏆 Fase final: '+games.length+' encuentros');reportResults(null,'Fase final · '+s.postseason.stage,games.map(m=>m.id));}catch(e){toast(e.message)}break;}case 'simulate-cup':{try{const ms=simulateCupRound(s);save();toast(`🏆 Copa: ${ms.length} encuentros disputados`);reportResults(null,'Copa de las Provincias',ms.map(m=>m.id));}catch(e){toast(e.message)}break;}case 'custom-open':ui.competition=el.dataset.id;nav('torneos');break;case 'simulate-custom':{try{const title=s.competitions.find(c=>c.id===el.dataset.id)?.name||'Torneo';const m=simulateCustomRound(s,el.dataset.id);save();toast(`⚽ ${m.length} encuentros de torneo disputados`);reportResults(null,title,m.map(x=>x.id));}catch(e){toast(e.message)}break;}case 'next-season':{if(!confirm('¿Iniciar la próxima temporada? Se guardará el calendario anterior en el archivo histórico. Recomendamos exportar una copia JSON primero.'))return;try{const intl=ensureInternational(s);if(intl&&(!intl.champions.champion||!intl.horizonte.champion)){toast('⚠ Finalizá las dos Copas de Arcalis antes de pasar de temporada');break;}returnLoans(s);governanceSeason(s);prepareCountriesNextSeason(s,s.season+1);internationalArchiveNextSeason(s);const res=startNextSeason(s);save();ui.round=1;toast(`🏆 ¡Comienza el Apertura ${res.season}!`);nav('historia')}catch(e){toast(e.message)}break;}case 'history-season':{const a=s.archive?.find(x=>String(x.season)===String(el.dataset.id));if(!a)break;const games=a.fixtures.filter(played);modal('Archivo oficial · Apertura '+a.season,`<div class="stack"><div class="notice">🏆 Campeón anual: ${E(a.annual[0].name)} · Descendieron: ${E(a.relegated.join(', '))} · Ascendieron: ${E(a.promoted.join(', '))}</div><div class="card"><h3 class="h3">Todos los marcadores de ${a.season}</h3>${games.map(m=>`<div class="market-event"><span><span class="tiny muted">J${m.round} · ${m.competition}</span><br>${E(m.home)} <b>${m.scoreH}-${m.scoreA}</b> ${E(m.away)}</span>${button('📰 Acta','match',`data-id="${E(m.id)}"`,'btn sm')}</div>`).join('')}</div></div>`);break;}case 'market-loan':{try{const r=makeLoan(s,{buyer:marketBuyer(),seller:el.dataset.seller,id:el.dataset.id});save();toast('✍ Cesión: '+r.player);render()}catch(e){toast('⚠ '+e.message)}break;}
case 'market-clause':{try{const r=executeClause(s,{buyer:marketBuyer(),seller:el.dataset.seller,id:el.dataset.id});save();toast('💰 Cláusula ejecutada: '+r.player);render()}catch(e){toast('⚠ '+e.message)}break;}
case 'market-free':{try{const r=signFreeAgent(s,marketBuyer(),el.dataset.id);save();toast('✍ Agente libre fichado: '+r.player);render()}catch(e){toast('⚠ '+e.message)}break;}
case 'market-release':{if(!confirm('¿Dejar a este jugador como agente libre?'))break;try{const p=releaseToMarket(s,marketBuyer(),el.dataset.id);save();toast('Jugador liberado: '+p.name);render()}catch(e){toast('⚠ '+e.message)}break;}
case 'market-open':{try{openMarket(s,s.leagueRound>=18?`Mercado pos-Apertura ${s.season}`:`Mercado extraordinario · Apertura ${s.season}`);save();toast('💰 Abrió la ventana de pases');render();}catch(e){toast(e.message)}break;}case 'market-next':{try{const r=advanceMarketDay(s);save();toast(r.closed?`¡Mercado cerrado! ${r.report.transfers} traspasos`:`Día ${r.day}: ${r.added.length} fichajes automáticos`);render();}catch(e){toast(e.message)}break;}case 'market-finish':{if(!confirm('¿Simular el resto de la ventana? Los demás clubes realizarán fichajes automáticos y se cerrará el mercado.'))return;try{const r=finishMarket(s);save();toast(`⚡ Cierre del mercado: ${r.report.transfers} fichajes`);render();}catch(e){toast(e.message)}break;}case 'market-offer':marketOfferModal(el.dataset.name,el.dataset.id);break;case 'market-accept':{try{const r=acceptMarketCounter(s,el.dataset.id);save();toast('✍ Contrato firmado: '+r.player);render();}catch(e){toast(e.message)}break;}case 'market-decline':{try{rejectMarketCounter(s,el.dataset.id);save();render();}catch(e){toast(e.message)}break;}case 'market-scout':{const yes=toggleMarketScout(s,el.dataset.id);save();toast(yes?'⚑ Jugador agregado a seguimiento':'Jugador retirado de seguimiento');render();break;}case 'market-academy':{try{const p=recruitAcademyPlayer(s,marketBuyer());save();toast('🌱 Ascendió de cantera: '+p.name+' · POT '+p.pot);render();}catch(e){toast(e.message)}break;}case 'market-train':{try{const name=marketBuyer();const result=trainClub(s,name);save();toast('🏋 Mejoran: '+(result.join(', ')||'plantilla'));render();}catch(e){toast(e.message)}break;}case 'match':paper(lookupMatch(el.dataset.id));break;case 'show-results':reportResults(Number(el.dataset.round));break;case 'comp-report':{const c=s.competitions.find(c=>c.id===el.dataset.id);if(c){const done=c.fixtures.filter(played);if(done.length)reportResults(null,c.name,done.slice(-32).map(m=>m.id));else toast('Este torneo todavía no tiene resultados.')}break;}case 'club':clubModal(el.dataset.name);break;case 'player':playerModal(el.dataset.player,el.dataset.name);break;case 'news':showNews(el.dataset.id);break;case 'shirt':ui.shirt=Number(el.dataset.id);render();break;case 'coach':coachModal(el.dataset.name);break;case 'go-office':ui.team=el.dataset.name;close();nav('directivas');break;case 'close':close();break;case 'close-overlay':if(el.classList.contains('backdrop'))close();break;case 'print':window.print();break;case 'export':{const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='noveria-partida-2026-j'+leagueSummary(s).round+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('💾 Copia descargada');break;}case 'reset':if(confirm('¿Restablecer Noveria? Se perderá todo el progreso de este navegador si no tenés una copia.')){s=ensureExtraMarket(ensureEcosystem(ensureContinent(freshState())));save();ui.round=7;toast('Universo restaurado a Jornada 6');nav('inicio')}break;}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el)onAction(el)});
document.addEventListener('keydown',event=>{if(event.key==='Escape')close();if(event.key==='Enter'&&event.target.matches('.fixture'))onAction(event.target)});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='countrySelect'){ui.country=el.value;render()}else if(el.id==='liveMatchSelect'){stopLive();ui.liveMatch=el.value;ui.liveMinute=0;render()}else if(el.id==='manageClubV4'){ui.team=el.value;render()}else if(el.id==='roundSelect'){ui.round=Number(el.value);render()}else if(el.id==='formatSelect'){const h=$('formatHelp');if(h)h.textContent={league:'Puntos corridos a una vuelta.',league2:'Todos contra todos a ida y vuelta, localía equilibrada.',cup:'Cruces eliminatorios y penales. Clasificación directa, con pases automáticos si es necesario.',recopa:'Final a partido único y cancha neutral. Elegí exactamente dos clubes.',apertura:'Dos zonas de 9, 18 jornadas con fechas dobles, clásicos, semifinales, final y Recopa. Elegí 18 clubes.',groups:'Grupos de cuatro y fase final. Elegí 4, 8, 12, 16... hasta 32 clubes.'}[el.value]||''}else if(el.id==='clubFilter'){ui.clubFilter=el.value;render()}else if(el.id==='kitClub'){ui.team=el.value;ui.shirt=0;render()}else if(el.id==='marketClubSelect'){ui.marketClub=el.value;ui.team=el.value;render()}else if(el.id==='manageClub'){ui.team=el.value;if(s.mode==='manager'){s.managedClub=ui.team;save()}render()}else if(el.id==='modeSelect'){s.mode=el.value;s.managedClub=ui.team;save();toast(s.mode==='manager'?'Modo entrenador activado':'Modo presidente activado');render()}else if(el.id==='importFile'){
 const f=el.files?.[0];if(!f)return;f.text().then(txt=>{try{const data=validateImport(JSON.parse(txt));if(!confirm('¿Reemplazar esta partida por la copia importada?'))return;s=ensureExtraMarket(ensureEcosystem(ensureContinent(data)));save();ui.round=Math.min(18,getLeagueNextRound(s));toast('Partida recuperada');nav('inicio')}catch(e){toast('Error al importar: '+e.message)}});
 }});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='liveMinuteSlider'){ui.liveMinute=Number(el.value);stopLive();render();return;}if(el.id==='clubSearch'){ui.clubSearch=el.value;const old=document.querySelector('.clubgrid');if(old){const holder=document.createElement('div');holder.innerHTML=clubGrid();old.replaceWith(holder.firstElementChild)}}else if(el.id==='playerSearch'){ui.playerQuery=el.value;/* Se aplica la búsqueda cuando cambia el campo */}});
document.addEventListener('change',event=>{if(event.target.id==='playerSearch')render()});
document.addEventListener('submit',event=>{const form=event.target;if(!form.id)return;event.preventDefault();try{const v=new FormData(form);if(form.id==='careerForm'){s.career.name=String(v.get('coachName')||'Entrenador').trim().slice(0,60);save();toast('Perfil actualizado');render();return;}if(form.id==='marketSearchForm'){ui.marketSearch=String(v.get('search')||'').trim();ui.marketPos=String(v.get('pos')||'TODAS');ui.marketSort=String(v.get('sort')||'overall');render();return;}else if(form.id==='marketOfferForm'){const offer=submitMarketOffer(s,{buyer:String(v.get('buyer')),seller:String(v.get('seller')),playerId:String(v.get('playerId')),fee:Number(v.get('fee')),wage:Number(v.get('wage')),years:Number(v.get('years'))});close();toast(offer.status==='accepted'?'✅ ¡Fichaje confirmado!':offer.status==='counter'?'↪ Recibiste una contraoferta':'✕ Oferta rechazada');save();nav('mercado');return;}else if(form.id==='kitForm'){const t=club(ui.team);t.kits[ui.shirt]={p:String(v.get('p')),s:String(v.get('s')),pattern:String(v.get('pattern')),sponsor:String(v.get('sponsor')||'NOVERIA').slice(0,18)};toast('👕 Uniforme guardado');}else if(form.id==='tacticsForm'){const t=club(ui.team);t.formation=String(v.get('formation'));t.tactic=String(v.get('tactic'));toast('Táctica actualizada');}else if(form.id==='coachForm'){changeCoach(s,String(v.get('club')),String(v.get('coach')));close();toast('Directiva: cambio de entrenador anunciado');}else if(form.id==='createCompForm'){const teams=[...form.querySelector('[name=teams]').selectedOptions].map(o=>o.value);const id=createCompetition(s,String(v.get('name')),teams,String(v.get('format')));s.competitions.find(c=>c.id===id).prize=Math.max(0,Math.min(10000000,Number(v.get('prize')||0)));ui.competition=id;toast('🏆 Torneo creado');}save();render();}catch(e){toast('⚠️ '+e.message)}});
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
async function initializeNoveria(){
 try{
  const restored=await restoreSave(STORAGE_KEY,isSaveValid);
  if(restored){s=ensureExtraMarket(ensureEcosystem(ensureContinent(ensureMarket(restored.state))));ui.round=Math.min(18,getLeagueNextRound(s));saveStatus={message:'✓ Partida recuperada',savedAt:restored.savedAt,ok:true};}
  else saveStatus={message:'Partida inicial · Jornada 7',savedAt:0,ok:true};
 }catch(error){console.warn('No se pudo recuperar el respaldo local',error);saveStatus={message:'Partida abierta · verificá tu respaldo',savedAt:0,ok:false}}
 render();showSaveStatus();
 // Graba también el primer acceso y migra copias antiguas al sistema doble.
 save();
}
initializeNoveria();
